function renderStudentRowWithFee(student) {
    const initials = `${student.firstName?.charAt(0) || ''}${student.lastName?.charAt(0) || ''}`.toUpperCase();
    const avatarColors = ['bg-red-500', 'bg-blue-500', 'bg-green-500', 'bg-purple-500', 'bg-pink-500'];
    const avatarColor = avatarColors[Math.floor(Math.random() * avatarColors.length)];
    
    // Calculate fee data if not already present
    const expectedPerTerm = student.expectedPerTerm || 0;
    const term1Paid = student.term1Paid || 0;
    const term2Paid = student.term2Paid || 0;
    const term3Paid = student.term3Paid || 0;
    const totalPaid = term1Paid + term2Paid + term3Paid;
    const totalExpected = expectedPerTerm * 3;
    const balance = totalExpected - totalPaid;
    
    const term1Status = term1Paid >= expectedPerTerm ? 'Paid' : term1Paid > 0 ? 'Partial' : 'Unpaid';
    const term2Status = term2Paid >= expectedPerTerm ? 'Paid' : term2Paid > 0 ? 'Partial' : 'Unpaid';
    const term3Status = term3Paid >= expectedPerTerm ? 'Paid' : term3Paid > 0 ? 'Partial' : 'Unpaid';
    
    const term1Color = term1Status === 'Paid' ? 'bg-green-100 text-green-800' : term1Status === 'Partial' ? 'bg-yellow-100 text-yellow-800' : 'bg-red-100 text-red-800';
    const term2Color = term2Status === 'Paid' ? 'bg-green-100 text-green-800' : term2Status === 'Partial' ? 'bg-yellow-100 text-yellow-800' : 'bg-red-100 text-red-800';
    const term3Color = term3Status === 'Paid' ? 'bg-green-100 text-green-800' : term3Status === 'Partial' ? 'bg-yellow-100 text-yellow-800' : 'bg-red-100 text-red-800';
    
    const overdueColor = balance > expectedPerTerm ? 'bg-red-100 text-red-800' : balance > 0 ? 'bg-orange-100 text-orange-800' : 'bg-green-100 text-green-800';
    const overdueText = balance > expectedPerTerm ? '⚠️ Critical Overdue' : balance > 0 ? '⚠️ Balance Due' : '✅ Good Standing';
    
    const feeStructureName = student.feeStructure?.name || student.feeAssignment?.feeStructureName || 'Not Assigned';
    const bursaryBadge = student.feeAssignment?.bursaryName ? `<span class="text-xs text-green-600 ml-1">🎖️ ${student.feeAssignment.bursaryName}</span>` : '';
    
    return `
        <tr class="border-b hover:bg-gray-50 transition ${balance > expectedPerTerm ? 'bg-red-50' : ''}" data-student-id="${student.id}">
            <td class="p-3"><input type="checkbox" class="student-checkbox" value="${student.id}" onchange="updateSelectedCount()"></td>
            <td class="p-3 font-mono text-sm">${student.admissionNumber || 'N/A'}</td>
            <td class="p-3"><div class="flex items-center space-x-2"><div class="w-8 h-8 ${avatarColor} rounded-full flex items-center justify-center text-white text-sm font-bold">${initials || 'S'}</div><div><p class="font-medium">${student.firstName || ''} ${student.lastName || ''}</p><p class="text-xs text-gray-500">${student.enrolledAt ? new Date(student.enrolledAt).toLocaleDateString() : 'N/A'}</p></div></div></td>
            <td class="p-3"><span class="px-2 py-1 rounded-full text-xs bg-purple-100 text-purple-800">${student.currentClass || 'Not Assigned'}</span></td>
            <td class="p-3 text-sm">${feeStructureName}${bursaryBadge}</td>
            <td class="p-3 text-right font-semibold">UGX ${expectedPerTerm.toLocaleString()}</td>
            <td class="p-3 text-right"><span class="px-2 py-1 rounded-full text-xs ${term1Color}">UGX ${term1Paid.toLocaleString()}</span></td>
            <td class="p-3 text-right"><span class="px-2 py-1 rounded-full text-xs ${term2Color}">UGX ${term2Paid.toLocaleString()}</span></td>
            <td class="p-3 text-right"><span class="px-2 py-1 rounded-full text-xs ${term3Color}">UGX ${term3Paid.toLocaleString()}</span></td>
            <td class="p-3 text-right font-semibold">UGX ${totalPaid.toLocaleString()}</td>
            <td class="p-3 text-right font-bold ${balance > 0 ? 'text-red-600' : 'text-green-600'}">UGX ${Math.abs(balance).toLocaleString()} ${balance > 0 ? '(Due)' : '(Overpaid)'}</td>
            <td class="p-3"><span class="px-2 py-1 rounded-full text-xs ${overdueColor}">${overdueText}</span></td>
            <td class="p-3"><div class="flex space-x-2"><button onclick="viewStudentDetails('${student.id}')" class="text-blue-600"><i class="fas fa-eye"></i></button><button onclick="viewStudentFeeDetails('${student.id}')" class="text-purple-600"><i class="fas fa-money-bill-wave"></i></button><button onclick="makePaymentForStudent('${student.id}')" class="text-green-600"><i class="fas fa-receipt"></i></button></div></td>
        </tr>
    `;
}

// ==================== FILTER FUNCTIONS ====================
function initializeStudentFilters() {
    const searchInput = document.getElementById('searchInput');
    const classFilter = document.getElementById('classFilter');
    const feeStatusFilter = document.getElementById('feeStatusFilter');
    
    const filters = [searchInput, classFilter, feeStatusFilter];
    filters.forEach(filter => {
        if (filter) {
            filter.addEventListener('input', applyStudentFilters);
            filter.addEventListener('change', applyStudentFilters);
        }
    });
    
    applyStudentFilters();
}

function applyStudentFilters() {
    const searchTerm = document.getElementById('searchInput')?.value.toLowerCase() || '';
    const classValue = document.getElementById('classFilter')?.value || '';
    const feeStatusValue = document.getElementById('feeStatusFilter')?.value || '';
    
    filteredStudents = window.allStudentsData.filter(student => {
        const matchesSearch = searchTerm === '' || (student.firstName && student.firstName.toLowerCase().includes(searchTerm)) || (student.lastName && student.lastName.toLowerCase().includes(searchTerm)) || (student.admissionNumber && student.admissionNumber.toLowerCase().includes(searchTerm));
        const matchesClass = classValue === '' || student.currentClass === classValue;
        let matchesFeeStatus = true;
        if (feeStatusValue !== '') {
            if (feeStatusValue === 'paid') matchesFeeStatus = student.balance <= 0;
            else if (feeStatusValue === 'partial') matchesFeeStatus = student.balance > 0 && student.balance <= student.expectedPerTerm;
            else if (feeStatusValue === 'overdue') matchesFeeStatus = student.balance > student.expectedPerTerm;
            else if (feeStatusValue === 'critical') matchesFeeStatus = student.balance > (student.expectedPerTerm * 2);
        }
        return matchesSearch && matchesClass && matchesFeeStatus;
    });
    
    currentPage = 1;
    updateStudentTableDisplay();
}

function updateStudentTableDisplay() {
    const startIndex = (currentPage - 1) * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    const pageStudents = filteredStudents.slice(startIndex, endIndex);
    
    const tbody = document.getElementById('studentsTableBody');
    if (tbody) {
        tbody.innerHTML = pageStudents.map(student => renderStudentRowWithFee(student)).join('');
    }
    
    const totalPages = Math.ceil(filteredStudents.length / itemsPerPage);
    const showingStart = filteredStudents.length === 0 ? 0 : startIndex + 1;
    const showingEnd = Math.min(endIndex, filteredStudents.length);
    
    const showingStartSpan = document.getElementById('showingStart');
    const showingEndSpan = document.getElementById('showingEnd');
    const totalCountSpan = document.getElementById('totalCount');
    const pageInfoSpan = document.getElementById('pageInfo');
    
    if (showingStartSpan) showingStartSpan.textContent = showingStart;
    if (showingEndSpan) showingEndSpan.textContent = showingEnd;
    if (totalCountSpan) totalCountSpan.textContent = filteredStudents.length;
    if (pageInfoSpan) pageInfoSpan.textContent = `Page ${currentPage} of ${Math.ceil(filteredStudents.length / itemsPerPage) || 1}`;
    
    const prevBtn = document.querySelector('#paginationControls button:first-child');
    const nextBtn = document.querySelector('#paginationControls button:last-child');
    if (prevBtn) prevBtn.disabled = currentPage === 1;
    if (nextBtn) nextBtn.disabled = currentPage === Math.ceil(filteredStudents.length / itemsPerPage);
}

function previousPage() {
    if (currentPage > 1) {
        currentPage--;
        updateStudentTableDisplay();
    }
}

function nextPage() {
    const totalPages = Math.ceil(filteredStudents.length / itemsPerPage);
    if (currentPage < totalPages) {
        currentPage++;
        updateStudentTableDisplay();
    }
}

function filterCriticalOverdue() {
    const feeStatusFilter = document.getElementById('feeStatusFilter');
    if (feeStatusFilter) {
        feeStatusFilter.value = 'critical';
        applyStudentFilters();
    }
}

// ==================== SELECTION FUNCTIONS ====================
function toggleSelectAll() {
    const checkboxes = document.querySelectorAll('.student-checkbox');
    const selectAllCheckbox = document.getElementById('selectAllCheckbox');
    const isChecked = selectAllCheckbox?.checked || false;
    
    checkboxes.forEach(checkbox => {
        checkbox.checked = isChecked;
        if (isChecked) selectedStudents.add(checkbox.value);
        else selectedStudents.delete(checkbox.value);
    });
    updateSelectedCount();
}

function updateSelectedCount() {
    const checkboxes = document.querySelectorAll('.student-checkbox:checked');
    selectedStudents.clear();
    checkboxes.forEach(cb => selectedStudents.add(cb.value));
    
    const count = selectedStudents.size;
    const selectAllCheckbox = document.getElementById('selectAllCheckbox');
    if (selectAllCheckbox) {
        const totalCheckboxes = document.querySelectorAll('.student-checkbox').length;
        selectAllCheckbox.checked = count === totalCheckboxes && totalCheckboxes > 0;
        selectAllCheckbox.indeterminate = count > 0 && count < totalCheckboxes;
    }
}

function exportSelectedStudents() {
    if (selectedStudents.size === 0) {
        alert('Please select at least one student to export');
        return;
    }
    
    const selectedData = window.allStudentsData.filter(s => selectedStudents.has(s.id));
    const exportData = selectedData.map(student => ({
        'Admission Number': student.admissionNumber, 'First Name': student.firstName, 'Last Name': student.lastName,
        'Gender': student.gender, 'Current Class': student.currentClass, 'Fee Structure': student.feeStructure?.name || 'Not Assigned',
        'Bursary': student.feeAssignment?.bursaryName || 'None', 'Expected Per Term': student.expectedPerTerm,
        'Term 1 Paid': student.term1Paid, 'Term 2 Paid': student.term2Paid, 'Term 3 Paid': student.term3Paid,
        'Total Paid': student.totalPaid, 'Balance': student.balance, 'Status': student.overdueMessage,
        'Registration Paid': student.registrationPaid ? 'Yes' : 'No', 'Parent Name': student.parentInfo?.name,
        'Parent Phone': student.parentInfo?.phone
    }));
    
    const csv = convertToCSV(exportData);
    downloadCSV(csv, `students_export_${new Date().toISOString().split('T')[0]}.csv`);
    alert(`✅ ${selectedStudents.size} students exported successfully`);
}

function sendBulkReminders() {
    if (selectedStudents.size === 0) {
        alert('Please select at least one student');
        return;
    }
    const selectedData = window.allStudentsData.filter(s => selectedStudents.has(s.id));
    const overdueStudents = selectedData.filter(s => s.balance > 0);
    if (overdueStudents.length === 0) {
        alert('No overdue balances among selected students');
        return;
    }
    alert(`📧 Reminders would be sent to ${overdueStudents.length} students with outstanding balances.\n\nTotal outstanding: UGX ${overdueStudents.reduce((sum, s) => sum + s.balance, 0).toLocaleString()}`);
}


