function printFeeStatement(studentId) {
    const student = window.allStudentsData.find(s => s.id === studentId);
    if (!student) return;
    let feePayments = JSON.parse(localStorage.getItem('feePaymentsSystem') || '[]');
    const studentPayments = feePayments.filter(p => p.studentId === studentId);
    const printWindow = window.open('', '_blank');
    printWindow.document.write(`<!DOCTYPE html><html><head><title>Fee Statement - ${student.firstName} ${student.lastName}</title><style>body{font-family:Arial;padding:40px}.header{text-align:center;margin-bottom:30px}.title{font-size:24px;font-weight:bold}.info{margin:20px 0;padding:15px;background:#f5f5f5;border-radius:5px}.info-row{display:flex;justify-content:space-between;margin:5px 0}table{width:100%;border-collapse:collapse;margin:20px 0}th,td{border:1px solid #ddd;padding:10px;text-align:left}th{background:#f0f0f0}.total-row{font-weight:bold;background:#f9f9f9}.footer{text-align:center;margin-top:30px;font-size:12px;color:#666}@media print{body{padding:0}}</style></head><body><div class="header"><div class="title">FEE STATEMENT</div><div>${currentSchool?.schoolName || 'School Name'}</div><div>Generated: ${new Date().toLocaleDateString()}</div></div><div class="info"><div class="info-row"><strong>Student Name:</strong> ${student.firstName} ${student.lastName}</div><div class="info-row"><strong>Admission Number:</strong> ${student.admissionNumber}</div><div class="info-row"><strong>Class:</strong> ${student.currentClass || 'Not Assigned'}</div><div class="info-row"><strong>Fee Structure:</strong> ${student.feeStructure?.name || 'Not Assigned'}</div><div class="info-row"><strong>Bursary:</strong> ${student.feeAssignment?.bursaryName || 'None'}</div></div><table><thead><tr><th>Date</th><th>Receipt No.</th><th>Term</th><th>Description</th><th>Amount (UGX)</th></tr></thead><tbody>${studentPayments.map(p => `<tr><td>${new Date(p.date).toLocaleDateString()}</td><td>${p.receiptNumber}</td><td>${p.term === 0 ? 'Registration' : `Term ${p.term}`}</td><td>${p.feeStructureName || 'Fee Payment'}</td><td>UGX ${p.amount.toLocaleString()}</td></tr>`).join('')}<tr class="total-row"><td colspan="4"><strong>Total Paid</strong></td><td><strong>UGX ${student.totalPaid.toLocaleString()}</strong></td></tr><tr><td colspan="4"><strong>Total Expected (Year)</strong></td><td><strong>UGX ${student.totalExpected.toLocaleString()}</strong></td></tr><tr><td colspan="4"><strong>Outstanding Balance</strong></td><td><strong>UGX ${Math.max(0, student.balance).toLocaleString()}</strong></td></tr></tbody></table><div class="footer">This is a computer-generated statement. Please contact the accounts office for any queries.</div></body></html>`);
    printWindow.document.close();
    printWindow.print();
}

function showFeeSummaryReport() {
    const students = window.allStudentsData || [];
    const totalExpected = students.reduce((sum, s) => sum + s.totalExpected, 0);
    const totalPaid = students.reduce((sum, s) => sum + s.totalPaid, 0);
    const totalOutstanding = totalExpected - totalPaid;
    const paidStudents = students.filter(s => s.balance <= 0).length;
    const partialStudents = students.filter(s => s.balance > 0 && s.balance <= s.expectedPerTerm).length;
    const overdueStudents = students.filter(s => s.balance > s.expectedPerTerm).length;
    
    const modalHtml = `<div class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50"><div class="bg-white rounded-2xl p-6 max-w-2xl w-full mx-4"><div class="flex justify-between items-start mb-4"><h3 class="text-2xl font-bold">Fee Summary Report</h3><button onclick="closeModal()" class="text-gray-500 hover:text-gray-700"><i class="fas fa-times text-2xl"></i></button></div><div class="space-y-4"><div class="grid grid-cols-2 gap-4"><div class="bg-blue-50 p-4 rounded-lg text-center"><p class="text-sm text-gray-600">Total Expected Fees</p><p class="text-2xl font-bold text-blue-600">UGX ${totalExpected.toLocaleString()}</p></div><div class="bg-green-50 p-4 rounded-lg text-center"><p class="text-sm text-gray-600">Total Collected</p><p class="text-2xl font-bold text-green-600">UGX ${totalPaid.toLocaleString()}</p></div><div class="bg-orange-50 p-4 rounded-lg text-center"><p class="text-sm text-gray-600">Outstanding Balance</p><p class="text-2xl font-bold text-orange-600">UGX ${totalOutstanding.toLocaleString()}</p></div><div class="bg-purple-50 p-4 rounded-lg text-center"><p class="text-sm text-gray-600">Collection Rate</p><p class="text-2xl font-bold text-purple-600">${totalExpected > 0 ? ((totalPaid / totalExpected) * 100).toFixed(1) : 0}%</p></div></div><div class="border-t pt-4"><h4 class="font-bold mb-3">Student Payment Status</h4><div class="space-y-2"><div class="flex justify-between items-center"><span>Fully Paid Students</span><span class="font-semibold text-green-600">${paidStudents}</span></div><div class="w-full bg-gray-200 rounded-full h-2"><div class="bg-green-600 rounded-full h-2" style="width: ${(paidStudents / students.length * 100)}%"></div></div><div class="flex justify-between items-center mt-2"><span>Partial Payment</span><span class="font-semibold text-yellow-600">${partialStudents}</span></div><div class="w-full bg-gray-200 rounded-full h-2"><div class="bg-yellow-600 rounded-full h-2" style="width: ${(partialStudents / students.length * 100)}%"></div></div><div class="flex justify-between items-center mt-2"><span>Overdue Students</span><span class="font-semibold text-red-600">${overdueStudents}</span></div><div class="w-full bg-gray-200 rounded-full h-2"><div class="bg-red-600 rounded-full h-2" style="width: ${(overdueStudents / students.length * 100)}%"></div></div></div></div><div class="flex gap-3 mt-4"><button onclick="exportFeeReport()" class="flex-1 bg-blue-600 text-white px-4 py-2 rounded-lg">Export Report</button><button onclick="closeModal()" class="flex-1 bg-gray-300 text-gray-700 px-4 py-2 rounded-lg">Close</button></div></div></div></div>`;
    document.body.insertAdjacentHTML('beforeend', modalHtml);
}

function exportFeeReport() {
    const students = window.allStudentsData || [];
    const exportData = students.map(s => ({ 'Admission Number': s.admissionNumber, 'Student Name': `${s.firstName} ${s.lastName}`, 'Class': s.currentClass, 'Fee Structure': s.feeStructure?.name || 'Not Assigned', 'Bursary': s.feeAssignment?.bursaryName || 'None', 'Expected Per Term': s.expectedPerTerm, 'Term 1 Paid': s.term1Paid, 'Term 2 Paid': s.term2Paid, 'Term 3 Paid': s.term3Paid, 'Total Paid': s.totalPaid, 'Total Expected': s.totalExpected, 'Outstanding Balance': s.balance, 'Status': s.balance <= 0 ? 'Fully Paid' : s.balance > s.expectedPerTerm ? 'Overdue' : 'Partial', 'Registration Fee Status': s.registrationPaid ? 'Paid' : 'Pending' }));
    const csv = convertToCSV(exportData);
    downloadCSV(csv, `fee_summary_report_${new Date().toISOString().split('T')[0]}.csv`);
    alert('✅ Report exported successfully');
}

function convertToCSV(data) {
    if (data.length === 0) return '';
    const headers = Object.keys(data[0]);
    const csvRows = [headers.join(',')];
    for (const row of data) {
        const values = headers.map(header => { const value = row[header] || ''; return `"${String(value).replace(/"/g, '""')}"`; });
        csvRows.push(values.join(','));
    }
    return csvRows.join('\n');
}

function downloadCSV(csv, filename) {
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    a.click();
    URL.revokeObjectURL(url);
}

function closeModal() {
    const modal = document.querySelector('.fixed.inset-0');
    if (modal) modal.remove();
}

