async function renderArchiveTab(container) {
    console.log('📦 Loading archive tab...');
    
    try {
        const archiveRes = await fetch('/api/students/archive');
        let archivedStudents = [];
        
        if (archiveRes.ok) {
            const data = await archiveRes.json();
            archivedStudents = data.archivedStudents || data || [];
            console.log(`📦 Found ${archivedStudents.length} archived students`);
        } else {
            console.warn('Archive API not available (status:', archiveRes.status, ')');
            // Don't try fallback - just show empty state
            container.innerHTML = `
                <div class="text-center py-12 text-gray-500">
                    <i class="fas fa-archive text-5xl mb-4 text-gray-300"></i>
                    <p class="text-lg font-medium">No archived students</p>
                    <p class="text-sm">Students who complete P.7 will appear here</p>
                    <p class="text-xs text-gray-400 mt-2">(Archive API not available)</p>
                </div>
            `;
            return;
        }

        if (!archivedStudents || archivedStudents.length === 0) {
            container.innerHTML = `
                <div class="text-center py-12 text-gray-500">
                    <i class="fas fa-archive text-5xl mb-4 text-gray-300"></i>
                    <p class="text-lg font-medium">No archived students</p>
                    <p class="text-sm">Students who complete P.7 will appear here</p>
                </div>
            `;
            return;
        }

        console.log(`📦 Rendering ${archivedStudents.length} archived students`);

        let html = `
            <div class="space-y-4">
                <div class="bg-blue-50 p-3 rounded-lg border border-blue-200 text-sm text-blue-700 flex items-center gap-2">
                    <i class="fas fa-info-circle"></i>
                    <span><strong>${archivedStudents.length}</strong> students have been archived after completing P.7</span>
                </div>
                <div class="overflow-x-auto max-h-96 overflow-y-auto border rounded-lg">
                    <table class="w-full text-sm">
                        <thead class="bg-gray-100 sticky top-0 z-10">
                            <tr>
                                <th class="p-3 text-left">Admission</th>
                                <th class="p-3 text-left">Name</th>
                                <th class="p-3 text-left">Last Class</th>
                                <th class="p-3 text-left">Archived Date</th>
                                <th class="p-3 text-center">Actions</th>
                            </tr>
                        </thead>
                        <tbody>
                            ${archivedStudents.map((record, index) => {
                                const student = record.student || record;
                                const name = `${student.firstName || ''} ${student.lastName || ''}`.trim() || 'Unknown';
                                const admission = student.admissionNumber || 'N/A';
                                const archivedAt = record.archivedAt ? new Date(record.archivedAt).toLocaleDateString() : (student.archivedAt ? new Date(student.archivedAt).toLocaleDateString() : 'Unknown');
                                const lastClass = student.currentClassName || record.fromClass || student.currentClass || 'P.7';
                                const studentId = student.id || record.id || index;
                                
                                return `
                                    <tr class="border-b hover:bg-gray-50">
                                        <td class="p-3 font-mono text-xs">${admission}</td>
                                        <td class="p-3 font-medium">${name}</td>
                                        <td class="p-3">${lastClass}</td>
                                        <td class="p-3 text-sm text-gray-500">${archivedAt}</td>
                                        <td class="p-3 text-center">
                                            <button onclick="viewArchivedStudent('${studentId}')" 
                                                    class="text-blue-600 hover:text-blue-800 text-sm bg-blue-50 hover:bg-blue-100 px-2 py-1 rounded transition">
                                                <i class="fas fa-eye"></i> View
                                            </button>
                                            <button onclick="restoreArchivedStudent('${studentId}')" 
                                                    class="text-green-600 hover:text-green-800 text-sm bg-green-50 hover:bg-green-100 px-2 py-1 rounded transition ml-1">
                                                <i class="fas fa-undo"></i> Restore
                                            </button>
                                        </td>
                                    </tr>
                                `;
                            }).join('')}
                        </tbody>
                    </table>
                </div>
            </div>
        `;

        container.innerHTML = html;

    } catch (error) {
        console.error('❌ Error loading archive:', error);
        container.innerHTML = `
            <div class="text-center py-8 text-red-500">
                <i class="fas fa-exclamation-triangle text-3xl mb-2"></i>
                <p>Error loading archived students: ${error.message}</p>
                <button onclick="loadPromotionTab('archive')" class="mt-2 bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700">
                    <i class="fas fa-sync-alt"></i> Retry
                </button>
            </div>
        `;
    }
}
