window.viewArchivedStudent = viewArchivedStudent;
window.viewArchivedFinancialStatus = viewArchivedFinancialStatus;
window.restoreArchivedStudent = restoreArchivedStudent;

console.log('✅ Archived student functions loaded with financial status view');

// ==================== RESTORE ARCHIVED STUDENT ====================
async function restoreArchivedStudent(studentId) {
    console.log('🔄 Restoring archived student:', studentId);
    
    if (!confirm('Restore this student from archive? They will become active again.')) return;

    try {
        const response = await fetch(`/api/students/restore/${studentId}`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' }
        });

        if (!response.ok) {
            throw new Error(`Failed to restore: ${response.status}`);
        }

        const data = await response.json();
        showToast(`✅ ${data.message || 'Student restored successfully'}`, 'success');
        
        // Close modal if open
        const modal = document.getElementById('archiveViewModal');
        if (modal) modal.remove();
        
        // Refresh the archive tab
        loadPromotionTab('archive');
        
        // Also refresh other tabs
        window.promotionData = null;
        
    } catch (error) {
        console.error('❌ Error restoring student:', error);
        showToast(`❌ Failed to restore: ${error.message}`, 'error');
    }
}

// ==================== FIXED: FIND FEE STRUCTURE FOR CLASS/TYPE ====================
function findFeeStructureForClassAndType(className, studentType, feeStructures) {
    if (!className || !feeStructures) return null;

    const clean = className.toLowerCase().trim();
    const isBoarding = studentType === 'Boarding';

    console.log(`🔍 Looking for fee structure for TARGET class: "${clean}" (${studentType})`);

    // Build maps for Day and Boarding
    const dayMap = {};
    const boardingMap = {};

    feeStructures.forEach(fs => {
        if (!fs || fs.isActive === false) return;

        const name = fs.name.toLowerCase().trim();
        const isBoardingFS = name.includes('boarding');
        const isDayFS = name.includes('day');

        // Store by exact name
        if (isBoardingFS) {
            boardingMap[name] = fs;
            let base = name.replace('boarding', '').trim();
            boardingMap[base] = fs;
            boardingMap[base.replace(/\s/g, '')] = fs;
        }
        if (isDayFS || !isBoardingFS) {
            dayMap[name] = fs;
            let base = name.replace('day', '').trim();
            dayMap[base] = fs;
            dayMap[base.replace(/\s/g, '')] = fs;
        }

        // Map by number (P.5, Primary 5, etc.)
        const numMatch = fs.name.match(/(\d+)/);
        if (numMatch) {
            const num = numMatch[1];
            const pKey = `p.${num}`.toLowerCase();
            const primaryKey = `primary ${num}`.toLowerCase();

            if (isBoardingFS) {
                boardingMap[pKey] = fs;
                boardingMap[primaryKey] = fs;
                boardingMap[pKey.replace(/\s/g, '')] = fs;
                boardingMap[primaryKey.replace(/\s/g, '')] = fs;
            }
            if (isDayFS || !isBoardingFS) {
                dayMap[pKey] = fs;
                dayMap[primaryKey] = fs;
                dayMap[pKey.replace(/\s/g, '')] = fs;
                dayMap[primaryKey.replace(/\s/g, '')] = fs;
            }
        }

        // Map by level
        const levelMatch = fs.name.match(/(baby|middle|top|nursery)/i);
        if (levelMatch) {
            const level = levelMatch[1].toLowerCase();
            const levelMap = {
                'baby': 'baby class',
                'middle': 'middle class',
                'top': 'top class',
                'nursery': 'nursery'
            };
            const key = levelMap[level] || level;
            if (isBoardingFS) {
                boardingMap[key] = fs;
                boardingMap[key.replace(/\s/g, '')] = fs;
            }
            if (isDayFS || !isBoardingFS) {
                dayMap[key] = fs;
                dayMap[key.replace(/\s/g, '')] = fs;
            }
        }
    });

    // Choose the correct map based on student type
    const map = isBoarding ? boardingMap : dayMap;

    // TRY 1: Exact match
    if (map[clean]) {
        console.log(`   ✅ Found exact match: ${map[clean].name}`);
        return map[clean];
    }
    if (map[clean.replace(/\s/g, '')]) {
        console.log(`   ✅ Found match (no spaces): ${map[clean.replace(/\s/g, '')].name}`);
        return map[clean.replace(/\s/g, '')];
    }

    // TRY 2: Match by number (P.5, Primary 5, P5, etc.)
    const numMatch = clean.match(/(p\.?|primary)\s*(\d+)/i);
    if (numMatch) {
        const num = numMatch[2];
        const variants = [
            `p.${num}`,
            `primary ${num}`,
            `p${num}`,
            `primary${num}`,
            `p.${num}`.replace(/\s/g, ''),
            `primary ${num}`.replace(/\s/g, '')
        ];
        for (const v of variants) {
            if (map[v]) {
                console.log(`   ✅ Found by number ${num}: ${map[v].name}`);
                return map[v];
            }
        }
    }

    // TRY 3: Match by level
    const levelMatch = clean.match(/(baby|middle|top|nursery)/i);
    if (levelMatch) {
        const levelMap = {
            'baby': ['baby class', 'baby'],
            'middle': ['middle class', 'middle'],
            'top': ['top class', 'top'],
            'nursery': ['nursery']
        };
        const levelNames = levelMap[levelMatch[1].toLowerCase()] || [levelMatch[1].toLowerCase()];
        for (const lv of levelNames) {
            if (map[lv]) {
                console.log(`   ✅ Found by level: ${map[lv].name}`);
                return map[lv];
            }
            if (map[lv.replace(/\s/g, '')]) {
                console.log(`   ✅ Found by level (no spaces): ${map[lv.replace(/\s/g, '')].name}`);
                return map[lv.replace(/\s/g, '')];
            }
        }
    }

    // TRY 4: Partial match - any fee structure that contains the class name
    for (const [key, fs] of Object.entries(map)) {
        if (fs.name.toLowerCase().includes(clean) || clean.includes(fs.name.toLowerCase())) {
            console.log(`   ✅ Found partial match: ${fs.name}`);
            return fs;
        }
    }

    // TRY 5: Fallback - try the other type
    const fallbackMap = isBoarding ? dayMap : boardingMap;
    for (const [key, fs] of Object.entries(fallbackMap)) {
        if (fs.name.toLowerCase().includes(clean) || clean.includes(fs.name.toLowerCase())) {
            console.log(`   ⚠️ Fallback: Using ${isBoarding ? 'Day' : 'Boarding'} structure: ${fs.name}`);
            return fs;
        }
    }

    console.log(`   ❌ No fee structure found for "${className}" (${studentType})`);
    return null;
}

// ==================== RENDER INDIVIDUAL TAB ====================
function renderIndividualTab(students, classes, feeStructures, feeStructureMap) {
    if (!students || students.length === 0) {
        return `<div class="text-center py-8 text-gray-500"><i class="fas fa-users text-3xl mb-2"></i><p>No students enrolled</p></div>`;
    }

    // Get the correct next class for a student
    function getNextClassForStudent(student, allClasses) {
        if (!student || !student.currentClassName) return null;
        
        // Check if student is in P.7 - no next class
        if (student.isP7) {
            console.log(`🎓 ${student.firstName} is in P.7 - will be archived`);
            return null;
        }
        
        const currentName = student.currentClassName.trim();
        console.log(`🔍 Finding next class for: ${currentName} (Level: ${student.currentLevel})`);
        
        const sameLevelClasses = allClasses.filter(c => c.level === student.currentLevel);
        const sortedClasses = [...sameLevelClasses].sort((a, b) => {
            const numA = parseInt(a.name.match(/(\d+)/)?.[1] || '0');
            const numB = parseInt(b.name.match(/(\d+)/)?.[1] || '0');
            if (numA > 0 && numB > 0) return numA - numB;
            if (numA > 0) return -1;
            if (numB > 0) return 1;
            return a.name.localeCompare(b.name);
        });
        
        const currentIndex = sortedClasses.findIndex(c => c.id === student.currentClassId);
        if (currentIndex === -1) return null;
        
        const nextIndex = currentIndex + 1;
        if (nextIndex >= sortedClasses.length) {
            const levelOrder = ['Nursery', 'LowerPrimary', 'UpperPrimary'];
            const currentLevelIndex = levelOrder.indexOf(student.currentLevel);
            if (currentLevelIndex !== -1 && currentLevelIndex < levelOrder.length - 1) {
                const nextLevel = levelOrder[currentLevelIndex + 1];
                const nextLevelClasses = allClasses.filter(c => c.level === nextLevel);
                if (nextLevelClasses.length > 0) return nextLevelClasses[0];
            }
            return null;
        }
        
        return sortedClasses[nextIndex];
    }

    const levelOrder = ['Nursery', 'LowerPrimary', 'UpperPrimary'];

    return `
        <div class="space-y-4">
            <div class="bg-blue-50 p-3 rounded-lg border border-blue-200 text-sm text-blue-700 flex items-center gap-2">
                <i class="fas fa-info-circle"></i>
                <span>Select students to promote. <strong>P.7 students</strong> will be <strong>archived</strong> (marked as completed primary education).</span>
                <span class="ml-2 text-xs bg-purple-100 text-purple-800 px-2 py-0.5 rounded-full">🎓 P.7 → Archive</span>
            </div>

            <div class="flex flex-wrap gap-3 items-center">
                <div class="flex-1 min-w-[200px]">
                    <input type="text" id="individualSearch" placeholder="Search by name or admission..." 
                           class="w-full border rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-green-500 outline-none">
                </div>
                <button onclick="selectAllIndiv()" class="bg-gray-200 text-gray-700 px-3 py-2 rounded-lg text-sm hover:bg-gray-300 transition">Select All</button>
                <button onclick="deselectAllIndiv()" class="bg-gray-200 text-gray-700 px-3 py-2 rounded-lg text-sm hover:bg-gray-300 transition">Deselect All</button>
                <button onclick="clearIndivSelection()" class="bg-gray-200 text-gray-700 px-3 py-2 rounded-lg text-sm hover:bg-gray-300 transition">Clear</button>
            </div>

            <div class="overflow-x-auto max-h-96 overflow-y-auto border rounded-lg">
                <table class="w-full text-sm">
                    <thead class="bg-gray-100 sticky top-0 z-10">
                        <tr>
                            <th class="p-3 w-10"><input type="checkbox" id="indivSelectAll" onchange="toggleIndivAll()"></th>
                            <th class="p-3 text-left">Admission</th>
                            <th class="p-3 text-left">Name</th>
                            <th class="p-3 text-left">Current Class</th>
                            <th class="p-3 text-left">Promote To</th>
                            <th class="p-3 text-left">Fee Structure (Override)</th>
                            <th class="p-3 text-center">Type</th>
                        </tr>
                    </thead>
                    <tbody id="indivTable">
                        ${students.map(s => {
                            const nextClass = getNextClassForStudent(s, classes);
                            const defaultTargetId = nextClass ? nextClass.id : '';
                            const defaultTargetName = nextClass ? nextClass.name : (s.isP7 ? '🎓 ARCHIVE' : 'No next class');

                            // Determine student type
                            const isBoarding = s.studentType === 'Boarding';
                            const type = isBoarding ? 'Boarding' : 'Day';

                            // Auto-detect fee structure for the TARGET class
                            let autoFeeStructureId = '';
                            let autoFeeStructureName = 'Not Found';

                            if (defaultTargetId) {
                                const targetClass = classes.find(c => c.id === defaultTargetId);
                                if (targetClass) {
                                    const fee = findFeeStructureForClassAndType(targetClass.name, type, feeStructures);
                                    if (fee) {
                                        autoFeeStructureId = fee.id;
                                        autoFeeStructureName = fee.name;
                                    }
                                }
                            }

                            const isP7 = s.isP7 || false;

                            return `
                                <tr class="border-b hover:bg-gray-50 indiv-row ${isP7 ? 'bg-purple-50' : ''}" 
                                    data-name="${(s.firstName||'')+' '+(s.lastName||'')}".toLowerCase()
                                    data-admission="${s.admissionNumber||''}".toLowerCase()
                                    data-studentid="${s.id}">
                                    <td class="p-3 text-center">
                                        <input type="checkbox" class="indiv-cb" value="${s.id}" data-name="${(s.firstName||'')+' '+(s.lastName||'')}">
                                    </td>
                                    <td class="p-3 font-mono text-xs">${s.admissionNumber || 'N/A'}</td>
                                    <td class="p-3 font-medium">${s.firstName||''} ${s.lastName||''} ${isP7 ? '🎓' : ''}</td>
                                    <td class="p-3">${s.currentClassName || 'N/A'} ${isP7 ? '<span class="text-xs bg-purple-100 text-purple-700 px-1 py-0.5 rounded-full ml-1">P.7</span>' : ''}</td>
                                    <td class="p-3">
                                        ${isP7 ? `
                                            <span class="text-purple-600 font-semibold">🎓 ARCHIVE (Complete P.7)</span>
                                        ` : `
                                            <select class="indiv-target w-full border rounded px-2 py-1 text-sm" data-id="${s.id}">
                                                ${classes.map(c => `
                                                    <option value="${c.id}" ${defaultTargetId === c.id ? 'selected' : ''}>
                                                        ${c.name}
                                                    </option>
                                                `).join('')}
                                            </select>
                                        `}
                                    </td>
                                    <td class="p-3">
                                        ${isP7 ? `
                                            <span class="text-gray-400 text-sm">N/A - Archived</span>
                                        ` : `
                                            <select class="indiv-fee-override w-full border rounded px-2 py-1 text-sm" data-id="${s.id}" data-manually-selected="false">
                                                <option value="">${autoFeeStructureId ? `-- Auto (${autoFeeStructureName}) --` : '-- Auto (Not Found) --'}</option>
                                                ${feeStructures.filter(f => f.isActive !== false).map(f => `
                                                    <option value="${f.id}" ${autoFeeStructureId === f.id ? 'selected' : ''}>${f.name}</option>
                                                `).join('')}
                                            </select>
                                        `}
                                    </td>
                                    <td class="p-3 text-center">
                                        <span class="px-2 py-0.5 rounded-full text-xs ${isBoarding ? 'bg-blue-100 text-blue-800' : 'bg-green-100 text-green-800'}">
                                            ${isBoarding ? '🏠 Boarding' : '☀️ Day'}
                                        </span>
                                    </td>
                                </tr>
                            `;
                        }).join('')}
                    </tbody>
                </table>
            </div>

            <div class="flex justify-between items-center pt-4 border-t flex-wrap gap-3">
                <span class="text-sm text-gray-600">Selected: <span id="indivCount">0</span> students</span>
                <button onclick="promoteIndiv()" class="bg-green-600 text-white px-6 py-2 rounded-lg hover:bg-green-700 transition flex items-center gap-2">
                    <i class="fas fa-arrow-up"></i> Promote Selected
                </button>
            </div>
        </div>
    `;
}

// ==================== INIT INDIVIDUAL TAB ====================
function initIndividualTab(feeStructures, feeStructureMap) {
    // Search functionality
    const search = document.getElementById('individualSearch');
    if (search) {
        search.addEventListener('input', function() {
            const term = this.value.toLowerCase().trim();
            document.querySelectorAll('.indiv-row').forEach(row => {
                const name = (row.dataset.name || '').toLowerCase();
                const admission = (row.dataset.admission || '').toLowerCase();
                const matches = term === '' || name.includes(term) || admission.includes(term);
                row.style.display = matches ? '' : 'none';
            });
        });
    }

    // Target class change handler (only for non-P.7 students)
    document.querySelectorAll('.indiv-target').forEach(targetSelect => {
        targetSelect.addEventListener('change', function() {
            const studentId = this.dataset.id;
            const targetClassId = this.value;
            
            console.log(`🔄 Target class changed for student ${studentId} to: ${targetClassId}`);
            
            const feeOverride = document.querySelector(`.indiv-fee-override[data-id="${studentId}"]`);
            if (!feeOverride) return;

            const student = window.promotionData?.students?.find(s => s.id === studentId);
            if (!student) return;

            const targetClass = window.promotionData?.classes?.find(c => c.id === targetClassId);
            if (!targetClass) return;

            const isBoarding = student.studentType === 'Boarding';
            const type = isBoarding ? 'Boarding' : 'Day';

            const fee = findFeeStructureForClassAndType(targetClass.name, type, feeStructures);
            
            const wasManuallySelected = feeOverride.dataset.manuallySelected === 'true';
            const currentValue = feeOverride.value;
            
            feeOverride.innerHTML = '';
            
            const autoOption = document.createElement('option');
            autoOption.value = '';
            autoOption.textContent = fee ? `-- Auto (${fee.name}) --` : '-- Auto (Not Found) --';
            feeOverride.appendChild(autoOption);
            
            let autoFeeId = null;
            feeStructures.filter(f => f.isActive !== false).forEach(f => {
                const option = document.createElement('option');
                option.value = f.id;
                option.textContent = f.name;
                if (fee && fee.id === f.id) autoFeeId = f.id;
                feeOverride.appendChild(option);
            });
            
            const userOptionExists = currentValue && feeOverride.querySelector(`option[value="${currentValue}"]`);
            
            if (wasManuallySelected && userOptionExists && currentValue !== '') {
                feeOverride.value = currentValue;
                console.log(`✅ Keeping user's MANUAL selection: ${currentValue}`);
            } else if (fee) {
                feeOverride.value = fee.id;
                feeOverride.dataset.manuallySelected = 'false';
                console.log(`✅ Auto-selected: ${fee.id} (${fee.name})`);
            } else {
                feeOverride.value = '';
                feeOverride.dataset.manuallySelected = 'false';
            }
        });
    });

    // Track manual selections
    document.querySelectorAll('.indiv-fee-override').forEach(feeOverride => {
        feeOverride.addEventListener('change', function() {
            const selectedValue = this.value;
            if (selectedValue !== '') {
                this.dataset.manuallySelected = 'true';
            } else {
                this.dataset.manuallySelected = 'false';
            }
        });
    });

    document.querySelectorAll('.indiv-cb').forEach(cb => cb.addEventListener('change', updateIndivCount));
    updateIndivCount();
}

function updateIndivCount() {
    const checked = document.querySelectorAll('.indiv-cb:checked').length;
    const total = document.querySelectorAll('.indiv-cb').length;
    const countEl = document.getElementById('indivCount');
    if (countEl) countEl.textContent = checked;
    const selectAll = document.getElementById('indivSelectAll');
    if (selectAll) {
        selectAll.checked = checked === total && total > 0;
        selectAll.indeterminate = checked > 0 && checked < total;
    }
}

function toggleIndivAll() {
    const selectAll = document.getElementById('indivSelectAll');
    document.querySelectorAll('.indiv-cb').forEach(cb => cb.checked = selectAll.checked);
    updateIndivCount();
}

function selectAllIndiv() {
    document.querySelectorAll('.indiv-cb').forEach(cb => cb.checked = true);
    updateIndivCount();
}

function deselectAllIndiv() {
    document.querySelectorAll('.indiv-cb').forEach(cb => cb.checked = false);
    updateIndivCount();
}

function clearIndivSelection() {
    document.querySelectorAll('.indiv-cb').forEach(cb => cb.checked = false);
    updateIndivCount();
}

// ==================== PROMOTE INDIVIDUAL ====================
// ==================== PROMOTE INDIVIDUAL - FIXED FOR P.7 ====================
async function promoteIndiv() {
    console.log('=== PROMOTE INDIVIDUAL CALLED ===');

    const selected = document.querySelectorAll('.indiv-cb:checked');
    if (selected.length === 0) {
        showToast('Please select at least one student to promote.', 'warning');
        return;
    }

    // Build promotion items array
    const promotionItems = [];
    let hasInvalid = false;
    let hasOverride = false;
    let hasP7 = false;

    selected.forEach(cb => {
        const studentId = cb.value;
        const student = window.promotionData?.students?.find(s => s.id === studentId);
        
        // Check if student is P.7
        if (student?.isP7) {
            hasP7 = true;
            // For P.7 students, we need to send a valid class ID that the backend will recognize as "archive"
            // We'll use a special flag and also send the current class ID
            promotionItems.push({
                studentId: studentId,
                toClassId: student.currentClassId, // Send current class ID
                isP7: true,
                archive: true  // Explicit archive flag
            });
            return;
        }

        const targetSelect = document.querySelector(`.indiv-target[data-id="${studentId}"]`);
        const feeOverrideSelect = document.querySelector(`.indiv-fee-override[data-id="${studentId}"]`);

        if (!targetSelect || !targetSelect.value) {
            hasInvalid = true;
            return;
        }

        const item = {
            studentId: studentId,
            toClassId: targetSelect.value,
            isP7: false
        };

        if (feeOverrideSelect && feeOverrideSelect.value) {
            item.feeStructureId = feeOverrideSelect.value;
            hasOverride = true;
        }

        promotionItems.push(item);
    });

    if (hasInvalid) {
        showToast('One or more students do not have a target class selected.', 'error');
        return;
    }

    if (promotionItems.length === 0) {
        showToast('No valid students to promote.', 'error');
        return;
    }

    console.log(`📋 Promoting ${promotionItems.length} students`);
    console.log('Items:', promotionItems);

    // Build confirmation message
    let confirmMsg = `You are about to promote ${promotionItems.length} student(s).\n\n`;
    if (hasP7) {
        const p7Count = promotionItems.filter(i => i.isP7).length;
        confirmMsg += `🎓 ${p7Count} P.7 student(s) will be ARCHIVED.\n`;
        confirmMsg += `⚠️ They will be marked as "Inactive" and moved to the archive.\n\n`;
    }
    if (hasOverride) {
        confirmMsg += `⚠️ Some students have custom fee structure overrides.\n`;
    }
    confirmMsg += `\nContinue?`;

    if (!confirm(confirmMsg)) return;

    const btn = document.querySelector('#promotionTabContent button:last-child');
    const originalText = btn?.innerHTML || 'Promote Selected';
    if (btn) {
        btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Processing...';
        btn.disabled = true;
    }

    try {
        const payload = { items: promotionItems };
        console.log('📤 Sending promotion payload:', JSON.stringify(payload, null, 2));

        const res = await fetch('/api/students/promote', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Accept': 'application/json'
            },
            body: JSON.stringify(payload)
        });

        if (!res.ok) {
            let errorText = await res.text();
            console.error('Promotion error response:', errorText);
            throw new Error(`Promotion failed (${res.status}): ${errorText}`);
        }

        const data = await res.json();
        console.log('Promotion response:', data);

        if (data.success) {
            let msg = `✅ ${data.summary.successCount} students processed!\n\n`;
            if (data.summary.archivedCount > 0) {
                msg += `📦 ${data.summary.archivedCount} P.7 students ARCHIVED.\n`;
                msg += `   They have been marked as "Inactive" and moved to the archive.\n`;
            }
            if (data.summary.failedCount > 0) {
                msg += `❌ ${data.summary.failedCount} failed.\n`;
            }
            if (data.summary.skippedCount > 0) {
                msg += `⏭️ ${data.summary.skippedCount} skipped.\n`;
            }
            msg += `\n📅 New Academic Year: ${data.summary.nextAcademicYear || 'N/A'}`;

            if (data.archivedStudents && data.archivedStudents.length > 0) {
                msg += `\n\n📦 Archived Students:\n`;
                data.archivedStudents.slice(0, 5).forEach(s => {
                    msg += `   • ${s.studentName} → ARCHIVED (${s.fromClass})\n`;
                });
                if (data.archivedStudents.length > 5) {
                    msg += `   ... and ${data.archivedStudents.length - 5} more\n`;
                }
            }

            alert(msg);
            showStudentPromotion();
        } else {
            alert('❌ Promotion failed: ' + (data.error || 'Unknown error'));
        }
    } catch (error) {
        console.error('❌ Promotion error:', error);
        alert('❌ Error promoting students: ' + error.message + '\n\nPlease check the console for more details.');
    } finally {
        if (btn) {
            btn.innerHTML = originalText;
            btn.disabled = false;
        }
    }
}

// ==================== CLASS TAB ====================
function renderClassTab(students, classes, currentYear, nextYear) {
    // Group students by their current class
    const classGroups = {};
    classes.forEach(c => {
        const count = students.filter(s => s.currentClassId === c.id).length;
        if (count > 0) classGroups[c.id] = { class: c, count };
    });

    if (Object.keys(classGroups).length === 0) {
        return `<div class="text-center py-8 text-gray-500">No students in any class</div>`;
    }

    return `
        <div class="space-y-4">
            <div class="bg-blue-50 p-3 rounded-lg border border-blue-200 text-sm text-blue-700 flex items-center gap-2">
                <i class="fas fa-info-circle"></i>
                <span>Promote all students in a class to the <strong>next class</strong>. <strong>P.7 students</strong> will be <strong>archived</strong>.</span>
                <span class="ml-2 text-xs bg-purple-100 text-purple-800 px-2 py-0.5 rounded-full">🎓 P.7 → Archive</span>
            </div>
            <div class="grid grid-cols-1 md:grid-cols-2 gap-4">
                ${Object.values(classGroups).map(({ class: cls, count }) => {
                    const isP7 = cls.name.toLowerCase().trim() === 'p.7' || 
                                 cls.name.toLowerCase().trim() === 'primary 7' ||
                                 cls.name.toLowerCase().trim() === 'p7';
                    
                    const nextClass = isP7 ? null : getNextClassForClass(cls, classes);
                    const nextClassName = isP7 ? '🎓 ARCHIVE (P.7 Completed)' : (nextClass ? nextClass.name : 'No next class');
                    const targetValue = isP7 ? '' : (nextClass ? nextClass.id : '');
                    
                    return `
                        <div class="border rounded-lg p-4 hover:shadow-md transition ${isP7 ? 'bg-purple-50 border-purple-300' : ''}">
                            <div class="flex justify-between items-center">
                                <div>
                                    <h3 class="font-bold text-lg ${isP7 ? 'text-purple-700' : ''}">${cls.name} ${isP7 ? '🎓' : ''}</h3>
                                    <p class="text-sm text-gray-500">${count} student(s)</p>
                                    ${isP7 ? `<p class="text-xs text-purple-600 font-semibold">Will be ARCHIVED</p>` : ''}
                                </div>
                                <span class="bg-blue-100 text-blue-700 px-2 py-1 rounded-full text-sm">${count}</span>
                            </div>
                            <div class="mt-3">
                                <select class="class-target w-full border rounded px-3 py-2 text-sm" data-from="${cls.id}" ${isP7 ? 'disabled' : ''}>
                                    ${classes.map(c => {
                                        const isSelected = nextClass && c.id === nextClass.id;
                                        return `<option value="${c.id}" ${isSelected ? 'selected' : ''}>${c.name}</option>`;
                                    }).join('')}
                                </select>
                                ${isP7 ? `
                                    <p class="text-xs text-purple-600 mt-1">🎓 Students will be archived (completed P.7)</p>
                                ` : nextClass ? `
                                    <p class="text-xs text-green-600 mt-1">Auto-suggested: ${nextClass.name}</p>
                                ` : `
                                    <p class="text-xs text-yellow-600 mt-1">⚠️ No next class found in this level</p>
                                `}
                            </div>
                            <button onclick="promoteClassAction('${cls.id}')" class="mt-3 w-full ${isP7 ? 'bg-purple-600 hover:bg-purple-700' : 'bg-green-600 hover:bg-green-700'} text-white px-4 py-2 rounded-lg transition">
                                <i class="fas ${isP7 ? 'fa-archive' : 'fa-arrow-up'}"></i> ${isP7 ? 'Archive' : 'Promote'} ${cls.name} (${count})
                            </button>
                        </div>
                    `;
                }).join('')}
            </div>
        </div>
    `;
}

// Helper: Get next class for a class
function getNextClassForClass(cls, allClasses) {
    if (!cls) return null;
    
    const isP7 = cls.name.toLowerCase().trim() === 'p.7' || 
                 cls.name.toLowerCase().trim() === 'primary 7' ||
                 cls.name.toLowerCase().trim() === 'p7';
    
    if (isP7) return null;
    
    const sameLevelClasses = allClasses.filter(c => c.level === cls.level);
    const sortedClasses = [...sameLevelClasses].sort((a, b) => {
        const numA = parseInt(a.name.match(/(\d+)/)?.[1] || '0');
        const numB = parseInt(b.name.match(/(\d+)/)?.[1] || '0');
        if (numA > 0 && numB > 0) return numA - numB;
        if (numA > 0) return -1;
        if (numB > 0) return 1;
        return a.name.localeCompare(b.name);
    });
    
    const currentIndex = sortedClasses.findIndex(c => c.id === cls.id);
    if (currentIndex === -1) return null;
    
    const nextIndex = currentIndex + 1;
    if (nextIndex >= sortedClasses.length) {
        const levelOrder = ['Nursery', 'LowerPrimary', 'UpperPrimary'];
        const currentLevelIndex = levelOrder.indexOf(cls.level);
        if (currentLevelIndex !== -1 && currentLevelIndex < levelOrder.length - 1) {
            const nextLevel = levelOrder[currentLevelIndex + 1];
            const nextLevelClasses = allClasses.filter(c => c.level === nextLevel);
            if (nextLevelClasses.length > 0) return nextLevelClasses[0];
        }
        return null;
    }
    
    return sortedClasses[nextIndex];
}

async function promoteClassAction(fromClassId) {
    const select = document.querySelector(`.class-target[data-from="${fromClassId}"]`);
    if (!select) return;
    
    const students = window.promotionData?.students?.filter(s => s.currentClassId === fromClassId) || [];
    if (students.length === 0) {
        showToast('No students in this class.', 'warning');
        return;
    }

    const isP7 = students.some(s => s.isP7);
    const action = isP7 ? 'archive' : 'promote';
    const actionLabel = isP7 ? 'ARCHIVE' : 'promote';

    if (!confirm(`Do you want to ${actionLabel} ${students.length} students from this class?${isP7 ? '\n\n🎓 P.7 students will be ARCHIVED.' : ''}`)) return;

    const btn = document.querySelector(`button[onclick="promoteClassAction('${fromClassId}')"]`);
    const originalText = btn?.innerHTML || 'Promote';
    if (btn) {
        btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Processing...';
        btn.disabled = true;
    }

    try {
        const payload = {
            fromClassId: fromClassId,
            toClassId: select.value || null
        };

        const res = await fetch('/api/students/promote', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });

        const data = await res.json();
        if (data.success) {
            let msg = `✅ ${data.summary.successCount} students processed!\n`;
            if (data.summary.archivedCount > 0) {
                msg += `📦 ${data.summary.archivedCount} P.7 students ARCHIVED.\n`;
            }
            alert(msg);
        } else {
            alert('❌ Operation failed: ' + (data.error || 'Unknown error'));
        }
        showStudentPromotion();
    } catch (e) {
        alert('❌ Error: ' + e.message);
    } finally {
        if (btn) {
            btn.innerHTML = originalText;
            btn.disabled = false;
        }
    }
}

// ==================== LEVEL TAB ====================
function renderLevelTab(students, classes) {
    const levels = ['Nursery', 'LowerPrimary', 'UpperPrimary'];
    const levelOrder = ['Nursery', 'LowerPrimary', 'UpperPrimary'];
    
    const data = levels.map(level => ({
        level,
        count: students.filter(s => s.currentLevel === level).length
    }));

    return `
        <div class="space-y-4">
            <div class="bg-blue-50 p-3 rounded-lg border border-blue-200 text-sm text-blue-700 flex items-center gap-2">
                <i class="fas fa-info-circle"></i>
                <span>Promote all students in a level to the <strong>next level</strong>. <strong>P.7 students</strong> in Upper Primary will be <strong>archived</strong>.</span>
            </div>
            ${data.map(({ level, count }) => {
                const currentIndex = levelOrder.indexOf(level);
                const nextLevel = (currentIndex !== -1 && currentIndex < levelOrder.length - 1) ? levelOrder[currentIndex + 1] : 'None';
                const nextLevelClasses = classes.filter(c => c.level === nextLevel);
                const nextLevelName = nextLevelClasses.length > 0 ? nextLevelClasses[0].name : 'No classes in next level';
                
                // Check if this is UpperPrimary (which contains P.7)
                const hasP7 = level === 'UpperPrimary' && students.some(s => s.currentLevel === 'UpperPrimary' && s.isP7);
                
                return `
                    <div class="border rounded-lg p-4 flex justify-between items-center hover:shadow-md transition ${hasP7 ? 'bg-purple-50' : ''}">
                        <div>
                            <h3 class="font-bold text-lg">${level}</h3>
                            <p class="text-sm text-gray-500">${count} student(s) → ${nextLevel}</p>
                            ${nextLevel !== 'None' && nextLevelClasses.length > 0 ? `
                                <p class="text-xs text-green-600">Target: ${nextLevelName}</p>
                            ` : `
                                <p class="text-xs text-yellow-600">⚠️ No target level</p>
                            `}
                            ${hasP7 ? `<p class="text-xs text-purple-600">🎓 P.7 students will be ARCHIVED</p>` : ''}
                        </div>
                        <button onclick="promoteLevelAction('${level}')" 
                                class="bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700 transition" 
                                ${count === 0 ? 'disabled' : ''}>
                            <i class="fas fa-arrow-up"></i> Promote ${level} (${count})
                        </button>
                    </div>
                `;
            }).join('')}
        </div>
    `;
}

