// ==================== EXPORT TEACHERS DATA ====================
function exportTeachersData() {
    if (window.allTeachersData.length === 0) { alert('No teachers to export'); return; }
    const exportData = window.allTeachersData.map(teacher => ({ 
        'Teacher ID': teacher.teacherId, 
        'First Name': teacher.firstName, 
        'Last Name': teacher.lastName, 
        'Gender': teacher.gender, 
        'Phone': teacher.phone, 
        'Email': teacher.email, 
        'Qualification': teacher.qualification, 
        'Specialization': teacher.specialization, 
        'Status': teacher.status, 
        'Employment Date': teacher.joinedAt ? new Date(teacher.joinedAt).toLocaleDateString() : 'N/A', 
        'Password': teacher.password || 'Not set',
        'Subjects': teacher.subjects?.map(s => { const subject = window.allSubjectsData?.find(sub => sub.id === s); return subject?.name; }).filter(Boolean).join(', ') || 'None', 
        'Classes': teacher.classes?.map(c => { const classObj = window.allClassesData?.find(cls => cls.id === c); return classObj?.name; }).filter(Boolean).join(', ') || 'None' 
    }));
    const csv = convertToCSV(exportData);
    downloadCSV(csv, `teachers_export_${new Date().toISOString().split('T')[0]}.csv`);
    addNotification('Teachers data exported successfully');
}

// ==================== CLOSE MODAL ====================
function closeModal() {
    const modal = document.querySelector('.fixed.inset-0');
    if (modal) modal.remove();
}

// ==================== ADD NOTIFICATION ====================
function addNotification(message) {
    if (typeof window.addNotification === 'function') {
        window.addNotification(message);
    } else {
        console.log('Notification:', message);
    }
}

// ==================== CONVERT TO CSV ====================
function convertToCSV(data) {
    if (!data || data.length === 0) return '';
    const headers = Object.keys(data[0]);
    const rows = data.map(row => headers.map(header => {
        const value = row[header] !== undefined && row[header] !== null ? row[header] : '';
        return `"${String(value).replace(/"/g, '""')}"`;
    }).join(','));
    return [headers.join(','), ...rows].join('\n');
}

// ==================== DOWNLOAD CSV ====================
function downloadCSV(csv, filename) {
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    a.click();
    URL.revokeObjectURL(url);
}

