// Export Fee Structures to Excel (CSV)
async function exportFeeStructuresToExcel() {
    try {
        const response = await fetch('/api/fee/structures');
        const structures = await response.json();
        
        const exportData = structures.map(fs => {
            const activityTotal = (fs.activityComponents || []).reduce((sum, c) => sum + (c.amount || 0), 0);
            const developmentTotal = (fs.developmentComponents || []).reduce((sum, c) => sum + (c.amount || 0), 0);
            
            return {
                'Structure Name': fs.name || '',
                'Level': fs.level || '',
                'Tuition Fee': fs.tuition || 0,
                'Activity Fee Total': activityTotal,
                'Development Fee Total': developmentTotal,
                'Total Per Term': (fs.tuition || 0) + activityTotal + developmentTotal,
                'Activity Components': (fs.activityComponents || []).map(c => `${c.name}(${c.amount})`).join(', '),
                'Development Components': (fs.developmentComponents || []).map(c => `${c.name}(${c.amount})`).join(', '),
                'Tangible Items': (fs.tangibleRequirements || []).map(r => r.name).join(', '),
                'Status': fs.isActive ? 'Active' : 'Inactive',
                'Created': fs.createdAt ? new Date(fs.createdAt).toLocaleDateString() : ''
            };
        });
        
        downloadCSV(exportData, `fee_structures_export_${new Date().toISOString().split('T')[0]}.csv`);
        alert(`✅ ${structures.length} fee structures exported successfully!`);
    } catch (error) {
        console.error('Error exporting fee structures:', error);
        alert('❌ Error exporting fee structures: ' + error.message);
    }
}

// Export All Data to Excel (Multiple Sheets in separate files)
async function exportAllToExcel() {
    try {
        // Fetch all data
        const [studentsRes, teachersRes, classesRes, subjectsRes, feePaymentsRes, feeStructuresRes] = await Promise.all([
            fetch('/api/students'),
            fetch('/api/teachers'),
            fetch('/api/school/classes'),
            fetch('/api/school/subjects'),
            fetch('/api/fee/payments'),
            fetch('/api/fee/structures')
        ]);
        
        let students = await studentsRes.json();
        let teachers = await teachersRes.json();
        let classes = await classesRes.json();
        let subjects = await subjectsRes.json();
        let payments = await feePaymentsRes.json();
        let structures = await feeStructuresRes.json();
        
        // Process students with class names
        students = students.map(student => {
            let currentClass = 'Not Assigned';
            if (student.currentClassId) {
                const classObj = classes.find(c => c.id === student.currentClassId);
                currentClass = classObj ? classObj.name : 'Not Assigned';
            }
            return { ...student, currentClass };
        });
        
        // Create zip with multiple CSV files
        const timestamp = new Date().toISOString().split('T')[0];
        const files = [
            { name: `students_${timestamp}.csv`, data: studentsToCSV(students) },
            { name: `teachers_${timestamp}.csv`, data: teachersToCSV(teachers) },
            { name: `classes_${timestamp}.csv`, data: classesToCSV(classes) },
            { name: `subjects_${timestamp}.csv`, data: subjectsToCSV(subjects) },
            { name: `payments_${timestamp}.csv`, data: paymentsToCSV(payments) },
            { name: `fee_structures_${timestamp}.csv`, data: feeStructuresToCSV(structures) }
        ];
        
        // Download each file separately
        for (const file of files) {
            const blob = new Blob([file.data], { type: 'text/csv' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = file.name;
            a.click();
            URL.revokeObjectURL(url);
            await new Promise(resolve => setTimeout(resolve, 100));
        }
        
        alert(`✅ All data exported successfully!\n\nFiles downloaded:\n- Students (${students.length})\n- Teachers (${teachers.length})\n- Classes (${classes.length})\n- Subjects (${subjects.length})\n- Payments (${payments.length})\n- Fee Structures (${structures.length})`);
    } catch (error) {
        console.error('Error exporting all data:', error);
        alert('❌ Error exporting all data: ' + error.message);
    }
}

// Helper function to convert array to CSV
function arrayToCSV(data) {
    if (!data || data.length === 0) return '';
    const headers = Object.keys(data[0]);
    const rows = data.map(row => headers.map(header => {
        const value = row[header] || '';
        return `"${String(value).replace(/"/g, '""')}"`;
    }).join(','));
    return [headers.join(','), ...rows].join('\n');
}

// Helper function to download CSV
function downloadCSV(data, filename) {
    const csv = arrayToCSV(data);
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', filename);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
}

// Individual CSV conversion functions
function studentsToCSV(students) {
    return students.map(s => ({
        'Admission Number': s.admissionNumber || '',
        'First Name': s.firstName || '',
        'Last Name': s.lastName || '',
        'Gender': s.gender || '',
        'Class': s.currentClass || 'Not Assigned',
        'Status': s.status || 'Active',
        'Parent Name': s.parentInfo?.name || '',
        'Parent Phone': s.parentInfo?.phone || '',
        'Parent Email': s.parentInfo?.email || '',
        'Address': s.address || '',
        'Enrollment Date': s.enrolledAt ? new Date(s.enrolledAt).toLocaleDateString() : ''
    }));
}

function teachersToCSV(teachers) {
    return teachers.map(t => ({
        'Teacher ID': t.teacherId || '',
        'First Name': t.firstName || '',
        'Last Name': t.lastName || '',
        'Gender': t.gender || '',
        'Phone': t.phone || '',
        'Email': t.email || '',
        'Qualification': t.qualification || '',
        'Specialization': t.specialization || '',
        'Status': t.status || 'Active',
        'Joined Date': t.joinedAt || '',
        'Address': t.address || ''
    }));
}

function classesToCSV(classes) {
    return classes.map(c => ({
        'Class Name': c.name || '',
        'Level': c.level || '',
        'Order': c.order || 0,
        'Created': c.createdAt ? new Date(c.createdAt).toLocaleDateString() : ''
    }));
}

function subjectsToCSV(subjects) {
    return subjects.map(s => ({
        'Subject Name': s.name || '',
        'Subject Code': s.code || '',
        'Category': s.category || '',
        'Description': s.description || '',
        'Created': s.createdAt ? new Date(s.createdAt).toLocaleDateString() : ''
    }));
}

function paymentsToCSV(payments) {
    return payments.map(p => ({
        'Date': p.date ? new Date(p.date).toLocaleDateString() : '',
        'Receipt Number': p.receiptNumber || '',
        'Student Name': p.studentName || '',
        'Admission Number': p.admissionNumber || '',
        'Term': p.term || '',
        'Amount': p.totalAmount || p.amount || 0,
        'Method': (p.method || 'cash').toUpperCase(),
        'Reference': p.reference || ''
    }));
}

function feeStructuresToCSV(structures) {
    return structures.map(fs => ({
        'Structure Name': fs.name || '',
        'Level': fs.level || '',
        'Tuition Fee': fs.tuition || 0,
        'Total Per Term': fs.total || 0,
        'Status': fs.isActive ? 'Active' : 'Inactive'
    }));
}

// ==================== RESTORE FUNCTIONS ====================

async function restoreFromBackup() {
    const fileInput = document.getElementById('restoreFile');
    if (!fileInput.files || fileInput.files.length === 0) {
        alert('Please select a backup file to restore');
        return;
    }
    
    const file = fileInput.files[0];
    if (!file.name.endsWith('.json')) {
        alert('Please select a valid JSON backup file');
        return;
    }
    
    const reader = new FileReader();
    reader.onload = async function(e) {
        try {
            const backupData = JSON.parse(e.target.result);
            
            const confirmMsg = `⚠️ WARNING: Restoring will overwrite ALL current data!\n\nThis will replace:\n- ${backupData.students?.length || 0} students\n- ${backupData.teachers?.length || 0} teachers\n- ${backupData.feePayments?.length || 0} payments\n\nType "RESTORE" to confirm.`;
            
            const confirmation = prompt(confirmMsg);
            if (confirmation !== 'RESTORE') {
                alert('Restore cancelled');
                return;
            }
            
            // Restore each data type
            if (backupData.students) {
                await fetch('/api/students/bulk', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(backupData.students)
                }).catch(() => {});
            }
            
            if (backupData.teachers) {
                await fetch('/api/teachers/bulk', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(backupData.teachers)
                }).catch(() => {});
            }
            
            if (backupData.classes) {
                await fetch('/api/school/classes/bulk', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(backupData.classes)
                }).catch(() => {});
            }
            
            if (backupData.feePayments) {
                await fetch('/api/fee/payments/bulk', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(backupData.feePayments)
                }).catch(() => {});
            }
            
            alert('✅ Data restored successfully! The page will now refresh.');
            setTimeout(() => window.location.reload(), 1500);
            
        } catch (error) {
            console.error('Error restoring data:', error);
            alert('❌ Invalid backup file or error during restore: ' + error.message);
        }
    };
    reader.readAsText(file);
}

