// ========== PAY FULL PERIOD ==========
function payFullPeriod(periodKey, balance) {
    if (!balance || balance <= 0) {
        showToast('No balance to pay for this period', 'warning');
        return;
    }
    
    const periodData = window.multiPeriodData;
    if (!periodData) { 
        showToast('Period data not loaded', 'error');
        return; 
    }
    
    let period = null;
    let isCurrent = false;
    
    if (periodData.currentPeriod && periodData.currentPeriod.periodKey === periodKey) {
        period = periodData.currentPeriod;
        isCurrent = true;
    } else if (periodData.previousPeriods) {
        period = periodData.previousPeriods.find(p => p.periodKey === periodKey);
    }
    
    if (!period) { 
        showToast('Period not found', 'error');
        return; 
    }
    
    const periodLabel = isCurrent ? 'Current Period' : `${period.year} Term ${period.term}`;
    
    const confirmed = confirm(
        `⚠️ Pay full balance for ${periodLabel}?\n\n` +
        `💰 Amount: UGX ${formatMoney(balance)}\n` +
        `📦 Items: ${period.activity?.itemsRemaining || 0} item(s) remaining\n\n` +
        `This will mark this period as fully paid.`
    );
    
    if (!confirmed) return;
    
    const tuitionInput = document.getElementById(`tuitionAmount_${periodKey}`);
    if (tuitionInput) {
        tuitionInput.value = balance;
        tuitionInput.dispatchEvent(new Event('input'));
    }
    
    document.querySelectorAll(`#periodItems_${periodKey} .cash-amount-input`).forEach(input => {
        const maxCash = parseFloat(input.dataset.maxCash) || 0;
        if (maxCash > 0) { input.value = maxCash; input.dispatchEvent(new Event('input')); }
    });
    
    document.querySelectorAll(`#periodItems_${periodKey} .item-quantity-input`).forEach(input => {
        const maxItems = parseFloat(input.dataset.maxItems) || 0;
        if (maxItems > 0) { input.value = maxItems; input.dispatchEvent(new Event('input')); }
    });
    
    updatePeriodTotal(periodKey);
    submitPeriodPayment(periodKey);
}

// ========== RESET PERIOD FORM ==========
function resetPeriodForm(periodKey) {
    document.querySelectorAll(`#periodItems_${periodKey} .cash-amount-input`).forEach(input => {
        input.value = '0';
        input.dispatchEvent(new Event('input'));
    });
    
    document.querySelectorAll(`#periodItems_${periodKey} .item-quantity-input`).forEach(input => {
        input.value = '0';
        input.dispatchEvent(new Event('input'));
    });
    
    const tuitionInput = document.getElementById(`tuitionAmount_${periodKey}`);
    if (tuitionInput) tuitionInput.value = '0';
    
    const receiptInput = document.getElementById(`receiptNumber_${periodKey}`);
    if (receiptInput) receiptInput.value = '';
    const referenceInput = document.getElementById(`reference_${periodKey}`);
    if (referenceInput) referenceInput.value = '';
    const notesInput = document.getElementById(`notes_${periodKey}`);
    if (notesInput) notesInput.value = '';
    
    const currentDateTime = getCurrentDateTimeForInput();
    const dateInput = document.getElementById(`paymentDate_${periodKey}`);
    if (dateInput) dateInput.value = currentDateTime.date;
    const timeInput = document.getElementById(`paymentTime_${periodKey}`);
    if (timeInput) timeInput.value = currentDateTime.time;
    
    updatePeriodTotal(periodKey);
    showToast('✅ Form has been reset', 'success');
}

// ========== TOGGLE FUNCTIONS ==========
function togglePeriodForm(periodKey, collapseId, iconId) {
    const collapse = document.getElementById(collapseId);
    const icon = document.getElementById(iconId);
    
    if (!collapse) {
        console.warn('Collapse element not found for:', collapseId);
        return;
    }
    
    if (collapse.classList.contains('hidden')) {
        collapse.classList.remove('hidden');
        if (icon) {
            icon.classList.remove('fa-chevron-down');
            icon.classList.add('fa-chevron-up');
        }
        window.activeExpandedPeriod = periodKey;
    } else {
        collapse.classList.add('hidden');
        if (icon) {
            icon.classList.remove('fa-chevron-up');
            icon.classList.add('fa-chevron-down');
        }
        if (window.activeExpandedPeriod === periodKey) {
            window.activeExpandedPeriod = null;
        }
    }
}

function toggleStatusGroup(collapseId) {
    const element = document.getElementById(collapseId);
    if (!element) return;
    
    const icon = document.getElementById(`${collapseId}_icon`);
    
    if (element.classList.contains('hidden')) {
        element.classList.remove('hidden');
        if (icon) {
            icon.classList.remove('fa-chevron-down');
            icon.classList.add('fa-chevron-up');
        }
    } else {
        element.classList.add('hidden');
        if (icon) {
            icon.classList.remove('fa-chevron-up');
            icon.classList.add('fa-chevron-down');
        }
    }
}

function toggleItemHistory(historyId) {
    const element = document.getElementById(historyId);
    if (!element) return;
    
    if (!window.expandedHistories) window.expandedHistories = {};
    window.expandedHistories[historyId] = !window.expandedHistories[historyId];
    element.classList.toggle('hidden');
    
    const parentContainer = element.closest('.bg-white');
    if (parentContainer) {
        const button = parentContainer.querySelector('button');
        if (button) {
            const historyItems = element.querySelectorAll('.flex.justify-between.items-center').length;
            const isExpanded = window.expandedHistories[historyId];
            button.innerHTML = `
                <i class="fas ${isExpanded ? 'fa-chevron-up' : 'fa-chevron-down'}"></i>
                ${isExpanded ? 'Hide' : 'View'} History (${historyItems})
            `;
        }
    }
}

function expandAllPeriods() {
    document.querySelectorAll('[id^="periodCollapse_"]').forEach(el => {
        el.classList.remove('hidden');
    });
    document.querySelectorAll('[id^="periodIcon_"]').forEach(el => {
        el.classList.remove('fa-chevron-down');
        el.classList.add('fa-chevron-up');
    });
}

function collapseAllPeriods() {
    document.querySelectorAll('[id^="periodCollapse_"]').forEach(el => {
        const parent = el.closest('.border-2');
        if (parent && parent.classList.contains('border-blue-400')) return;
        el.classList.add('hidden');
    });
    document.querySelectorAll('[id^="periodIcon_"]').forEach(el => {
        const parent = el.closest('.border-2');
        if (parent && parent.classList.contains('border-blue-400')) {
            el.classList.remove('fa-chevron-down');
            el.classList.add('fa-chevron-up');
            return;
        }
        el.classList.remove('fa-chevron-up');
        el.classList.add('fa-chevron-down');
    });
}

function expandAllItems(periodKey) {
    const container = document.getElementById(`periodItems_${periodKey}`);
    if (!container) return;
    
    container.querySelectorAll('[id^="sg_"]').forEach(el => {
        el.classList.remove('hidden');
        const iconId = `${el.id}_icon`;
        const icon = document.getElementById(iconId);
        if (icon) {
            icon.classList.remove('fa-chevron-down');
            icon.classList.add('fa-chevron-up');
        }
    });
}

function toggleAllItems(periodKey) {
    const container = document.getElementById(`periodItems_${periodKey}`);
    if (!container) return;
    
    const allSgs = container.querySelectorAll('[id^="sg_"]');
    const areAllHidden = Array.from(allSgs).every(el => el.classList.contains('hidden'));
    
    allSgs.forEach(el => {
        if (areAllHidden) {
            el.classList.remove('hidden');
            const iconId = `${el.id}_icon`;
            const icon = document.getElementById(iconId);
            if (icon) {
                icon.classList.remove('fa-chevron-down');
                icon.classList.add('fa-chevron-up');
            }
        } else {
            el.classList.add('hidden');
            const iconId = `${el.id}_icon`;
            const icon = document.getElementById(iconId);
            if (icon) {
                icon.classList.remove('fa-chevron-up');
                icon.classList.add('fa-chevron-down');
            }
        }
    });
}

// ========== SEARCH AND FILTER ==========
function initializePeriodFilters() {
    filterPeriodItems();
}

function filterPeriodItems() {
    const searchTerm = (document.getElementById('periodItemSearch')?.value || '').toLowerCase().trim();
    const statusFilter = document.getElementById('periodStatusFilter')?.value || 'all';
    const typeFilter = document.getElementById('periodTypeFilter')?.value || 'all';
    
    const itemGroups = document.querySelectorAll('.item-group');
    let visibleCount = 0;
    
    itemGroups.forEach(group => {
        const items = group.querySelectorAll('[id^="item_"]');
        let groupHasVisible = false;
        
        items.forEach(item => {
            const nameEl = item.querySelector('.font-medium');
            const itemName = nameEl ? nameEl.innerText.replace('📦', '').trim().toLowerCase() : '';
            const status = item.dataset.itemStatus || 'unpaid';
            const periodType = item.dataset.itemPeriod || 'termly';
            
            let matchesSearch = true;
            if (searchTerm) matchesSearch = itemName.includes(searchTerm);
            
            let matchesStatus = true;
            if (statusFilter !== 'all') matchesStatus = status === statusFilter;
            
            let matchesType = true;
            if (typeFilter !== 'all') matchesType = periodType === typeFilter;
            
            const isVisible = matchesSearch && matchesStatus && matchesType;
            item.style.display = isVisible ? '' : 'none';
            if (isVisible) groupHasVisible = true;
        });
        
        group.style.display = groupHasVisible ? '' : 'none';
        if (groupHasVisible) visibleCount++;
    });
}

function clearPeriodFilters() {
    const searchInput = document.getElementById('periodItemSearch');
    const statusFilter = document.getElementById('periodStatusFilter');
    const typeFilter = document.getElementById('periodTypeFilter');
    
    if (searchInput) searchInput.value = '';
    if (statusFilter) statusFilter.value = 'all';
    if (typeFilter) typeFilter.value = 'all';
    
    filterPeriodItems();
    showToast('Filters cleared', 'info');
}

// ========== SHOW REMOVED ITEMS DETAILS ==========
function showRemovedItemsDetails() {
    const student = window.currentStudent;
    if (!student || !student.removedItems) {
        showToast('No removed items for this student', 'info');
        return;
    }

    const removedItems = student.removedItems;
    const activeEntries = Object.entries(removedItems).filter(([id, data]) => data.isActive !== false);
    const count = activeEntries.length;

    let itemsHtml = activeEntries.map(([id, data]) => {
        const itemName = data.itemName || id;
        const reason = data.reason || 'No reason provided';
        const removedAt = data.removedAt ? new Date(data.removedAt).toLocaleDateString() : '';
        const periodLabel = (data.academicYear !== undefined && data.term !== undefined)
            ? `${getTermName(data.term)} ${data.academicYear}`
            : 'All periods (legacy)';
        return `
            <div class="flex justify-between items-center p-2 border-b last:border-0 hover:bg-gray-50">
                <span>📦 ${escapeHtml(itemName)}</span>
                <span class="text-xs text-purple-600 font-medium">${periodLabel}</span>
                <span class="text-xs text-red-500">${escapeHtml(reason)}</span>
                <span class="text-xs text-gray-400">${removedAt}</span>
            </div>
        `;
    }).join('');

    const modalHtml = `
        <div class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 overflow-y-auto">
            <div class="bg-white rounded-2xl p-6 max-w-lg w-full mx-4 my-8">
                <div class="flex justify-between items-center mb-4">
                    <h3 class="text-xl font-bold text-red-600">❌ Removed Items (${count})</h3>
                    <button onclick="closeModal()" class="text-gray-500 text-2xl hover:text-gray-700">&times;</button>
                </div>
                <p class="text-sm text-gray-600 mb-4">Each item is only removed for the period shown — it still applies in other periods:</p>
                <div class="max-h-60 overflow-y-auto border rounded-lg">
                    ${itemsHtml || '<p class="text-center text-gray-400 py-4">No removed items</p>'}
                </div>
                <button onclick="closeModal()" class="mt-4 w-full bg-gray-300 text-gray-700 py-2 rounded-lg hover:bg-gray-400">Close</button>
            </div>
        </div>
    `;

    document.body.insertAdjacentHTML('beforeend', modalHtml);
}

// ========== SHOW CUSTOM ITEMS DETAILS ==========
function showCustomItemsDetails() {
    const student = window.currentStudent;
    if (!student || !student.customItemOverrides) {
        showToast('No custom items for this student', 'info');
        return;
    }
    
    const customItems = student.customItemOverrides;
    const count = Object.keys(customItems).length;
    
    let itemsHtml = Object.entries(customItems).map(([id, data]) => {
        if (!data || data.isActive === false) return '';
        const itemName = data.itemName || id;
        const customAmount = data.customAmount ? `UGX ${formatMoney(data.customAmount)}` : '';
        const customQuantity = data.customQuantity ? `Qty: ${data.customQuantity}` : '';
        const reason = data.reason || 'Customized';
        return `
            <div class="flex justify-between items-center p-2 border-b last:border-0 hover:bg-gray-50">
                <span>📦 ${escapeHtml(itemName)}</span>
                <div class="text-right">
                    <span class="text-xs text-orange-500">${customAmount}</span>
                    ${customQuantity ? `<span class="text-xs text-orange-500 ml-2">${customQuantity}</span>` : ''}
                </div>
                <span class="text-xs text-gray-400">${escapeHtml(reason)}</span>
            </div>
        `;
    }).filter(Boolean).join('');
    
    const modalHtml = `
        <div class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 overflow-y-auto">
            <div class="bg-white rounded-2xl p-6 max-w-md w-full mx-4 my-8">
                <div class="flex justify-between items-center mb-4">
                    <h3 class="text-xl font-bold text-orange-600">⚡ Custom Items (${count})</h3>
                    <button onclick="closeModal()" class="text-gray-500 text-2xl hover:text-gray-700">&times;</button>
                </div>
                <p class="text-sm text-gray-600 mb-4">These items have custom overrides for this student:</p>
                <div class="max-h-60 overflow-y-auto border rounded-lg">
                    ${itemsHtml || '<p class="text-center text-gray-400 py-4">No custom items</p>'}
                </div>
                <button onclick="closeModal()" class="mt-4 w-full bg-gray-300 text-gray-700 py-2 rounded-lg hover:bg-gray-400">Close</button>
            </div>
        </div>
    `;
    
    document.body.insertAdjacentHTML('beforeend', modalHtml);
}

// ========== TOGGLE PERIOD HISTORY MODAL ==========
function togglePeriodHistoryModal(periodKey) {
    const periodData = window.multiPeriodData;
    if (!periodData) return;
    
    let period = null;
    if (periodData.currentPeriod && periodData.currentPeriod.periodKey === periodKey) {
        period = periodData.currentPeriod;
    } else if (periodData.previousPeriods) {
        period = periodData.previousPeriods.find(p => p.periodKey === periodKey);
    }
    
    if (!period) {
        showToast('Period not found', 'error');
        return;
    }
    
    let historyHtml = `
        <div class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 overflow-y-auto">
            <div class="bg-white rounded-2xl p-6 max-w-3xl w-full mx-4 my-8 max-h-[90vh] overflow-y-auto">
                <div class="flex justify-between items-center mb-4 pb-3 border-b">
                    <h3 class="text-xl font-bold">📜 Payment History - ${period.year} Term ${period.term}</h3>
                    <button onclick="closeModal()" class="text-gray-500 text-2xl hover:text-gray-700">&times;</button>
                </div>
                <div class="space-y-4">
    `;
    
    if (period.payments && period.payments.length > 0) {
        const sortedPayments = [...period.payments].sort((a, b) => new Date(b.date) - new Date(a.date));
        
        historyHtml += `
            <div class="bg-gray-50 rounded-lg p-3">
                <div class="flex justify-between mb-2">
                    <span class="font-semibold">Total Paid:</span>
                    <span class="font-bold text-green-600">UGX ${formatMoney(period.total?.paid || 0)}</span>
                </div>
                <div class="flex justify-between">
                    <span class="font-semibold">Expected:</span>
                    <span class="font-bold">UGX ${formatMoney(period.total?.expected || 0)}</span>
                </div>
                <div class="flex justify-between">
                    <span class="font-semibold">Balance:</span>
                    <span class="font-bold ${(period.total?.balance || 0) > 0 ? 'text-red-600' : 'text-green-600'}">
                        UGX ${formatMoney(Math.abs(period.total?.balance || 0))}
                        ${(period.total?.balance || 0) > 0 ? ' (Due)' : ' (Paid)'}
                    </span>
                </div>
            </div>
            <div class="overflow-x-auto">
                <table class="w-full text-sm">
                    <thead class="bg-gray-100">
                        <tr>
                            <th class="p-2 text-left">Date</th>
                            <th class="p-2 text-left">Receipt</th>
                            <th class="p-2 text-right">Amount</th>
                            <th class="p-2 text-left">Method</th>
                            <th class="p-2 text-left">Type</th>
                        </tr>
                    </thead>
                    <tbody>
                        ${sortedPayments.map(p => `
                            <tr class="border-b">
                                <td class="p-2">${new Date(p.date).toLocaleDateString()}</td>
                                <td class="p-2 font-mono text-xs">${p.receiptNumber || 'N/A'}</td>
                                <td class="p-2 text-right font-semibold text-green-600">UGX ${formatMoney(p.amount || 0)}</td>
                                <td class="p-2">${(p.method || 'cash').toUpperCase()}</td>
                                <td class="p-2">${p.isPreviousBalancePayment ? '📋 Previous Balance' : '📅 Current'}</td>
                            </tr>
                        `).join('')}
                    </tbody>
                </table>
            </div>
        `;
    } else {
        historyHtml += `
            <div class="text-center py-8 text-gray-500">
                <i class="fas fa-receipt text-4xl mb-3"></i>
                <p>No payment records found for this period</p>
            </div>
        `;
    }
    
    if (period.activity && period.activity.items && period.activity.items.length > 0) {
        const paidItems = period.activity.items.filter(i => i.isFullyPaid);
        const partialItems = period.activity.items.filter(i => !i.isFullyPaid && (i.remainingAmount > 0 || i.remainingQuantity > 0));
        
        historyHtml += `
            <div class="border-t pt-3 mt-3">
                <h4 class="font-bold mb-2">📦 Item Status</h4>
                <div class="grid grid-cols-2 gap-2">
                    <div class="bg-green-50 rounded-lg p-2 text-center">
                        <p class="text-xs text-gray-500">Fully Paid</p>
                        <p class="text-lg font-bold text-green-600">${paidItems.length}</p>
                    </div>
                    <div class="bg-red-50 rounded-lg p-2 text-center">
                        <p class="text-xs text-gray-500">Partial/Unpaid</p>
                        <p class="text-lg font-bold text-red-600">${partialItems.length}</p>
                    </div>
                </div>
                ${partialItems.length > 0 ? `
                    <div class="mt-3 space-y-2">
                        ${partialItems.slice(0, 10).map(i => `
                            <div class="flex justify-between text-sm border-b pb-1">
                                <span>📦 ${escapeHtml(i.name)}</span>
                                <span class="${i.remainingAmount > 0 ? 'text-red-600' : 'text-orange-600'}">
                                    ${i.remainingAmount > 0 ? `UGX ${formatMoney(i.remainingAmount)}` : ''}
                                    ${i.remainingAmount > 0 && i.remainingQuantity > 0 ? ' + ' : ''}
                                    ${i.remainingQuantity > 0 ? `${i.remainingQuantity} items` : ''}
                                    ${i.remainingAmount === 0 && i.remainingQuantity === 0 ? '✅ Paid' : ''}
                                </span>
                            </div>
                        `).join('')}
                        ${partialItems.length > 10 ? `<p class="text-xs text-gray-500">+${partialItems.length - 10} more items</p>` : ''}
                    </div>
                ` : ''}
            </div>
        `;
    }
    
    historyHtml += `
                    <button onclick="closeModal()" class="w-full bg-gray-300 text-gray-700 py-2 rounded-lg mt-4">Close</button>
                </div>
            </div>
        </div>
    `;
    
    document.body.insertAdjacentHTML('beforeend', modalHtml);
}

// ========== HELPER: DEDUPLICATE HISTORIES ==========
function deduplicateHistories(histories) {
    if (!histories || histories.length === 0) return [];
    const seen = new Set();
    const unique = [];
    for (let h = 0; h < histories.length; h++) {
        const history = histories[h];
        const key = `${history.date || ''}_${history.type || ''}_${history.amount || 0}_${history.quantity || 0}_${history.receiptNumber || ''}`;
        if (!seen.has(key)) {
            seen.add(key);
            unique.push(history);
        }
    }
    return unique;
}


