// ==================== SET FULL TUITION AMOUNT ====================

function setFullTuitionAmount() {
    const checkbox = document.getElementById('fullTuitionCheck');
    const tuitionInput = document.getElementById('tuitionAmount');
    if (checkbox?.checked && tuitionInput) {
        tuitionInput.value = tuitionInput.max;
        calculateCollectionTotals();
    } else if (tuitionInput && !checkbox?.checked) {
        tuitionInput.value = 0;
        calculateCollectionTotals();
    }
}

// ==================== RESET COLLECTION FORM ====================

function resetCollectionFormFields() {
    const tuitionInput = document.getElementById('tuitionAmount');
    if (tuitionInput) tuitionInput.value = '0';
    
    const fullTuitionCheck = document.getElementById('fullTuitionCheck');
    if (fullTuitionCheck) fullTuitionCheck.checked = false;
    
    // Clear all payment inputs
    document.querySelectorAll('.cashAmount, .itemsBrought').forEach(input => {
        input.value = '';
    });
    
    // Reset payment type radios to cash
    document.querySelectorAll('.paymentTypeRadio[value="cash"]').forEach(radio => {
        radio.checked = true;
    });
    
    // Show cash inputs, hide item inputs
    document.querySelectorAll('.payment-input-group').forEach(group => {
        if (group.id && group.id.startsWith('cashInput')) {
            group.classList.remove('hidden');
        } else if (group.id && group.id.startsWith('itemInput')) {
            group.classList.add('hidden');
        }
    });
    
    // Reset all item totals
    document.querySelectorAll('[id^="itemTotal_"]').forEach(span => {
        span.innerHTML = 'UGX 0';
    });
    
    // Reset all item statuses
    document.querySelectorAll('[id^="itemStatus_"]').forEach(span => {
        span.innerHTML = '❌ Not Paid';
        span.className = 'font-medium px-2 py-0.5 rounded-full bg-red-100 text-red-600';
    });
    
    // Reset termly total
    const termlyTotalSpan = document.getElementById('termlyTotalAmount');
    if (termlyTotalSpan) termlyTotalSpan.innerHTML = 'UGX 0';
    
    // Clear payment details
    const paymentReference = document.getElementById('paymentReference');
    const paymentNotes = document.getElementById('paymentNotes');
    if (paymentReference) paymentReference.value = '';
    if (paymentNotes) paymentNotes.value = '';
    
    calculateCollectionTotals();
}

// ==================== SUBMIT FEE COLLECTION ====================

async function submitFeeCollection() {
    const student = window.currentCollectingStudent;
    const feeStructure = window.currentFeeStructure;
    
    if (!student) {
        alert('No student selected');
        return;
    }
    
    // Get tuition amount
    const tuitionPaid = Math.round(parseInt(document.getElementById('tuitionAmount')?.value) || 0);
    
    // Collect all activity item payments
    const activityItemPayments = [];
    const termlyItems = document.querySelectorAll('#termlyItemsContainer .bg-white.rounded-lg');
    
    for (const row of termlyItems) {
        // Get item details from the row data
        const itemName = row.querySelector('h4')?.innerText?.replace('📦 ', '') || '';
        const componentName = row.querySelector('.text-xs.text-gray-500')?.innerText || '';
        const unitPrice = parseInt(row.dataset.unitPrice) || 0;
        const quantityRequired = parseInt(row.dataset.remainingQty) || 0;
        
        // Determine payment type
        const cashRadio = row.querySelector('input[value="cash"]');
        const isCash = cashRadio && cashRadio.checked;
        
        let amountPaid = 0;
        let itemsBrought = 0;
        
        if (isCash) {
            const cashInput = row.querySelector('.cashAmount');
            amountPaid = Math.round(parseInt(cashInput?.value) || 0);
            if (amountPaid <= 0) continue;
        } else {
            const itemsInput = row.querySelector('.itemsBrought');
            itemsBrought = Math.round(parseInt(itemsInput?.value) || 0);
            if (itemsBrought <= 0) continue;
            amountPaid = itemsBrought * unitPrice;
        }
        
        activityItemPayments.push({
            periodType: 'termly',
            componentId: `comp_termly_${Date.now()}_${itemName.replace(/\s/g, '_')}`,
            componentName: componentName,
            itemId: itemName.replace(/\s/g, '_'),
            itemName: itemName,
            unitPrice: unitPrice,
            quantityRequired: quantityRequired,
            paymentType: isCash ? 'paid_cash' : 'brought_item',
            amountPaid: isCash ? amountPaid : null,
            itemsBrought: !isCash ? itemsBrought : null,
            cashEquivalent: !isCash ? amountPaid : null
        });
    }
    
    const activityTotal = activityItemPayments.reduce((sum, p) => 
        sum + (p.paymentType === 'paid_cash' ? (p.amountPaid || 0) : (p.cashEquivalent || 0)), 0);
    const totalAmount = tuitionPaid + activityTotal;
    
    if (totalAmount <= 0) {
        alert('Please enter an amount to pay or select items to pay');
        return;
    }
    
    const method = document.getElementById('paymentMethodSelect')?.value || 'cash';
    const reference = document.getElementById('paymentReference')?.value || '';
    const notes = document.getElementById('paymentNotes')?.value || '';
    
    const submitBtn = document.querySelector('#collectionForm button[type="button"]');
    const originalText = submitBtn.innerText;
    submitBtn.innerText = 'Processing...';
    submitBtn.disabled = true;
    
    try {
        const response = await fetch('/api/fee/payments/enhanced', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                studentId: student.id,
                studentName: `${student.firstName} ${student.lastName}`,
                admissionNumber: student.admissionNumber,
                term: currentAcademicSettings.currentTerm,
                academicYear: currentAcademicSettings.currentYear.toString(),
                feeStructureId: feeStructure?.id || null,
                feeStructureName: feeStructure?.name || 'General Fee',
                bursaryId: student.appliedBursary?.id || null,
                bursaryName: student.appliedBursary?.name || null,
                tuitionPaid: tuitionPaid,
                activityItemPayments: activityItemPayments,
                totalAmount: totalAmount,
                method: method,
                reference: reference,
                notes: notes
            })
        });
        
        const result = await response.json();
        
        if (response.ok) {
            const expected = student.totalExpected || 0;
            const newTotalPaid = (student.totalPaid || 0) + totalAmount;
            const newBalance = expected - newTotalPaid;
            
            let message = `✅ Payment recorded!\nReceipt: ${result.receiptNumber}\nAmount: UGX ${Math.round(totalAmount).toLocaleString()}\n`;
            if (newBalance < 0) {
                message += `\n⚠️ Credit created: UGX ${Math.round(Math.abs(newBalance)).toLocaleString()} (will apply to next term)`;
            } else if (newBalance === 0) {
                message += `\n🎉 Student is now FULLY PAID for this term!`;
            } else {
                message += `\nRemaining balance: UGX ${Math.round(newBalance).toLocaleString()}`;
            }
            
            alert(message);
            showFeeManagement();
        } else {
            alert('❌ Error: ' + (result.error || 'Unknown error'));
        }
    } catch (error) {
        console.error('Payment error:', error);
        alert('Network error: ' + error.message);
    } finally {
        submitBtn.innerText = originalText;
        submitBtn.disabled = false;
    }
}

// Make sure all functions are global
window.loadCollectionForm = loadCollectionForm;
window.togglePaymentInput = togglePaymentInput;
window.updateItemPayment = updateItemPayment;
window.updateTermlyTotal = updateTermlyTotal;
window.calculateCollectionTotals = calculateCollectionTotals;
window.setFullTuitionAmount = setFullTuitionAmount;
window.resetCollectionFormFields = resetCollectionFormFields;
window.submitFeeCollection = submitFeeCollection;

// ==================== EXTRACT ITEMS FROM ACTIVITIES ====================

function extractItemsFromActivities(activities) {
    const items = [];
    activities.forEach(activity => {
        (activity.items || []).forEach(item => {
            items.push({
                componentId: activity.id,
                componentName: activity.name,
                periodType: activity.periodType,
                itemId: item.id,
                itemName: item.name,
                quantity: item.quantity || 1,
                totalAmount: item.totalAmount || 0,
                unitPrice: item.unitPrice || (item.totalAmount / (item.quantity || 1)),
                isTangible: item.isTangible !== false
            });
        });
    });
    return items;
}

// ==================== RENDER FULL ACTIVITY SECTION ====================

function renderFullActivitySection(items, periodType, title, color, icon, note) {
    if (!items || items.length === 0) return '';
    
    const bgColor = color === 'purple' ? 'bg-purple-50' : color === 'green' ? 'bg-green-50' : 'bg-orange-50';
    const borderColor = color === 'purple' ? 'border-purple-300' : color === 'green' ? 'border-green-300' : 'border-orange-300';
    const textColor = color === 'purple' ? 'text-purple-600' : color === 'green' ? 'text-green-600' : 'text-orange-600';
    
    return `
        <div class="border-2 ${borderColor} rounded-lg p-4 ${bgColor}">
            <div class="flex justify-between items-center mb-3 flex-wrap gap-2">
                <div class="flex items-center gap-2">
                    <div class="bg-${color}-600 text-white rounded-full w-8 h-8 flex items-center justify-center text-sm">${icon}</div>
                    <h3 class="font-bold text-lg">${title}</h3>
                </div>
                <span class="text-xs text-gray-500 italic">${note}</span>
            </div>
            <div id="${periodType}ItemsContainer" class="space-y-4 max-h-[500px] overflow-y-auto pr-2">
                ${items.map(item => renderFullItemRow(item, periodType, color)).join('')}
            </div>
            <div class="mt-4 pt-3 border-t ${borderColor} flex justify-between items-center font-bold">
                <span>Total ${title}:</span>
                <span id="${periodType}TotalAmountFinal" class="${textColor} text-xl">UGX 0</span>
            </div>
        </div>
    `;
}

// ==================== RENDER FULL ITEM ROW ====================

function renderFullItemRow(item, periodType, color) {
    const uniqueId = `${periodType}_${item.itemId}`;
    const unitPrice = item.unitPrice;
    const quantity = item.quantity;
    const totalAmount = item.totalAmount;
    
    return `
        <div id="itemRow_${uniqueId}" class="bg-white rounded-lg p-4 border shadow-sm hover:shadow-md transition">
            <div class="flex justify-between items-start mb-3 flex-wrap gap-2">
                <div>
                    <h4 class="font-semibold text-md">📦 ${item.itemName}</h4>
                    <p class="text-xs text-gray-500">${item.componentName}</p>
                </div>
                <div class="text-right">
                    <p class="text-sm font-semibold text-${color}-600">UGX ${unitPrice.toLocaleString()} / each</p>
                    <p class="text-xs text-gray-500">Total: UGX ${totalAmount.toLocaleString()} (${quantity} items)</p>
                </div>
            </div>
            
            <!-- Payment Type Selection -->
            <div class="mb-3">
                <label class="block text-sm font-medium mb-2">Payment Type:</label>
                <div class="flex gap-6">
                    <label class="flex items-center cursor-pointer p-2 rounded-lg hover:bg-gray-50">
                        <input type="radio" name="paymentType_${uniqueId}" value="cash" 
                               class="mr-2 w-4 h-4 paymentTypeRadioFinal" data-item-id="${uniqueId}" data-period="${periodType}"
                               onchange="togglePaymentInputsFinal('${uniqueId}', 'cash')" checked>
                        <span class="text-sm">💵 Pay Cash</span>
                    </label>
                    <label class="flex items-center cursor-pointer p-2 rounded-lg hover:bg-gray-50">
                        <input type="radio" name="paymentType_${uniqueId}" value="item" 
                               class="mr-2 w-4 h-4 paymentTypeRadioFinal" data-item-id="${uniqueId}" data-period="${periodType}"
                               onchange="togglePaymentInputsFinal('${uniqueId}', 'item')">
                        <span class="text-sm">📦 Bring Item</span>
                    </label>
                </div>
            </div>
            
            <!-- Cash Payment Input -->
            <div id="cashInput_${uniqueId}" class="payment-input-group mb-3">
                <label class="block text-sm font-medium mb-1">Amount to Pay (UGX)</label>
                <input type="number" class="w-full border rounded-lg px-3 py-2 cashAmountInputFinal" 
                       data-item-id="${uniqueId}" data-period="${periodType}"
                       data-unit-price="${unitPrice}" data-quantity="${quantity}"
                       data-max-amount="${totalAmount}"
                       placeholder="Max: UGX ${totalAmount.toLocaleString()}"
                       oninput="updateItemPaymentFinal('${uniqueId}', 'cash', ${unitPrice}, ${quantity})">
                <div class="flex justify-between items-center mt-1">
                    <p class="text-xs text-gray-500">Remaining: UGX ${totalAmount.toLocaleString()} (${quantity} items)</p>
                    <p id="thatToSay_${uniqueId}" class="text-xs text-blue-600 font-medium"></p>
                </div>
            </div>
            
            <!-- Item Brought Input -->
            <div id="itemInput_${uniqueId}" class="payment-input-group hidden mb-3">
                <label class="block text-sm font-medium mb-1">Number of Items Brought</label>
                <input type="number" class="w-full border rounded-lg px-3 py-2 itemsBroughtInputFinal" 
                       data-item-id="${uniqueId}" data-period="${periodType}"
                       data-unit-price="${unitPrice}" data-quantity="${quantity}"
                       max="${quantity}" placeholder="Max: ${quantity} items"
                       oninput="updateItemPaymentFinal('${uniqueId}', 'item', ${unitPrice}, ${quantity})">
                <div class="flex justify-between items-center mt-1">
                    <p class="text-xs text-gray-500">Remaining: ${quantity} items (UGX ${totalAmount.toLocaleString()})</p>
                    <p id="thatToSay_${uniqueId}_item" class="text-xs text-blue-600 font-medium"></p>
                </div>
            </div>
            
            <!-- Item Summary -->
            <div class="mt-3 pt-2 border-t flex justify-between items-center">
                <span class="text-sm font-semibold">Amount for this item:</span>
                <span id="itemTotal_${uniqueId}" class="font-bold text-green-600 text-lg">UGX 0</span>
            </div>
            <div class="flex justify-between items-center text-xs mt-1">
                <span>Payment Status:</span>
                <span id="itemStatus_${uniqueId}" class="font-medium px-2 py-0.5 rounded-full bg-red-100 text-red-600">Not Paid</span>
            </div>
        </div>
    `;
}

// ==================== TOGGLE PAYMENT INPUTS FINAL ====================

function togglePaymentInputsFinal(itemId, type) {
    const cashInput = document.getElementById(`cashInput_${itemId}`);
    const itemInput = document.getElementById(`itemInput_${itemId}`);
    
    if (type === 'cash') {
        if (cashInput) cashInput.classList.remove('hidden');
        if (itemInput) itemInput.classList.add('hidden');
        const itemsInput = itemInput?.querySelector('.itemsBroughtInputFinal');
        if (itemsInput) itemsInput.value = '';
    } else {
        if (cashInput) cashInput.classList.add('hidden');
        if (itemInput) itemInput.classList.remove('hidden');
        const cashAmountInput = cashInput?.querySelector('.cashAmountInputFinal');
        if (cashAmountInput) cashAmountInput.value = '';
    }
    
    const unitPrice = parseFloat(document.querySelector(`#cashInput_${itemId} .cashAmountInputFinal`)?.dataset.unitPrice || 0);
    const quantity = parseInt(document.querySelector(`#cashInput_${itemId} .cashAmountInputFinal`)?.dataset.quantity || 0);
    updateItemPaymentFinal(itemId, type, unitPrice, quantity);
}

// ==================== UPDATE ITEM PAYMENT FINAL ====================

function updateItemPaymentFinal(itemId, type, unitPrice, maxQuantity) {
    let amount = 0;
    let itemsCovered = 0;
    
    if (type === 'cash') {
        const cashInput = document.querySelector(`#cashInput_${itemId} .cashAmountInputFinal`);
        let cashAmount = parseFloat(cashInput?.value) || 0;
        const maxAmount = parseFloat(cashInput?.dataset?.maxAmount) || 0;
        
        if (cashAmount < 0) cashAmount = 0;
        if (maxAmount > 0) cashAmount = Math.min(cashAmount, maxAmount);
        if (cashInput) cashInput.value = cashAmount || '';
        
        amount = cashAmount;
        itemsCovered = unitPrice > 0 ? (cashAmount / unitPrice) : 0;
        
        const ttsSpan = document.getElementById(`thatToSay_${itemId}`);
        if (ttsSpan) {
            ttsSpan.innerHTML = amount > 0 ? `That's to say: ~${itemsCovered.toFixed(2)} items` : '';
        }
    } else {
        const itemsInput = document.querySelector(`#itemInput_${itemId} .itemsBroughtInputFinal`);
        let itemsCount = parseInt(itemsInput?.value) || 0;
        
        if (itemsCount < 0) itemsCount = 0;
        itemsCovered = Math.min(itemsCount, maxQuantity);
        if (itemsInput) itemsInput.value = itemsCovered || '';
        
        amount = itemsCovered * unitPrice;
        
        const ttsSpan = document.getElementById(`thatToSay_${itemId}_item`);
        if (ttsSpan) {
            ttsSpan.innerHTML = itemsCovered > 0 ? `That's to say: UGX ${amount.toLocaleString()} for ${itemsCovered} items` : '';
        }
    }
    
    // Update item total display
    const totalSpan = document.getElementById(`itemTotal_${itemId}`);
    if (totalSpan) totalSpan.innerHTML = `UGX ${amount.toLocaleString()}`;
    
    // Update status
    const statusSpan = document.getElementById(`itemStatus_${itemId}`);
    const originalQuantity = maxQuantity;
    const remainingQuantity = originalQuantity - itemsCovered;
    
    if (statusSpan) {
        if (remainingQuantity <= 0) {
            statusSpan.innerHTML = '✓ Fully Paid';
            statusSpan.className = 'font-medium px-2 py-0.5 rounded-full bg-green-100 text-green-600';
        } else if (amount > 0 || itemsCovered > 0) {
            statusSpan.innerHTML = `⚠️ Partial (${itemsCovered}/${originalQuantity} items)`;
            statusSpan.className = 'font-medium px-2 py-0.5 rounded-full bg-yellow-100 text-yellow-600';
        } else {
            statusSpan.innerHTML = '❌ Not Paid';
            statusSpan.className = 'font-medium px-2 py-0.5 rounded-full bg-red-100 text-red-600';
        }
    }
    
    // Update period total
    const periodType = document.querySelector(`#cashInput_${itemId} .cashAmountInputFinal`)?.dataset.period || 
                       document.querySelector(`#itemInput_${itemId} .itemsBroughtInputFinal`)?.dataset.period || 'one_time';
    updatePeriodTotalFinal(periodType);
    calculateAllTotalsFinal();
}

// ==================== UPDATE PERIOD TOTAL FINAL ====================

function updatePeriodTotalFinal(periodType) {
    let total = 0;
    
    const cashInputs = document.querySelectorAll(`#${periodType}ItemsContainer .cashAmountInputFinal`);
    cashInputs.forEach(input => {
        total += parseFloat(input.value) || 0;
    });
    
    const itemInputs = document.querySelectorAll(`#${periodType}ItemsContainer .itemsBroughtInputFinal`);
    itemInputs.forEach(input => {
        const unitPrice = parseFloat(input.dataset.unitPrice) || 0;
        const itemsCount = parseInt(input.value) || 0;
        total += itemsCount * unitPrice;
    });
    
    const totalSpan = document.getElementById(`${periodType}TotalAmountFinal`);
    if (totalSpan) totalSpan.innerHTML = `UGX ${total.toLocaleString()}`;
}

// ==================== CALCULATE ALL TOTALS FINAL ====================

function calculateAllTotalsFinal() {
    const tuition = parseInt(document.getElementById('tuitionAmount')?.value) || 0;
    
    let oneTimeTotal = 0, termlyTotal = 0, yearlyTotal = 0;
    
    const oneTimeSpan = document.getElementById('one_timeTotalAmountFinal');
    if (oneTimeSpan) oneTimeTotal = parseInt(oneTimeSpan.innerText.replace(/[^0-9]/g, '')) || 0;
    
    const termlySpan = document.getElementById('termlyTotalAmountFinal');
    if (termlySpan) termlyTotal = parseInt(termlySpan.innerText.replace(/[^0-9]/g, '')) || 0;
    
    const yearlySpan = document.getElementById('yearlyTotalAmountFinal');
    if (yearlySpan) yearlyTotal = parseInt(yearlySpan.innerText.replace(/[^0-9]/g, '')) || 0;
    
    const grandTotal = tuition + oneTimeTotal + termlyTotal + yearlyTotal;
    
    const summaryTuition = document.getElementById('summaryTuitionFinal');
    const summaryOneTime = document.getElementById('summaryOneTimeFinal');
    const summaryTermly = document.getElementById('summaryTermlyFinal');
    const summaryYearly = document.getElementById('summaryYearlyFinal');
    const summaryTotal = document.getElementById('summaryTotalFinal');
    const outstandingSpan = document.getElementById('outstandingAfterFinal');
    
    if (summaryTuition) summaryTuition.innerHTML = `UGX ${tuition.toLocaleString()}`;
    if (summaryOneTime) summaryOneTime.innerHTML = `UGX ${oneTimeTotal.toLocaleString()}`;
    if (summaryTermly) summaryTermly.innerHTML = `UGX ${termlyTotal.toLocaleString()}`;
    if (summaryYearly) summaryYearly.innerHTML = `UGX ${yearlyTotal.toLocaleString()}`;
    if (summaryTotal) summaryTotal.innerHTML = `UGX ${grandTotal.toLocaleString()}`;
    
    const expected = window.currentCollectingStudent?.totalExpected || 0;
    const currentPaid = window.currentCollectingStudent?.totalPaid || 0;
    const totalAfterPayment = currentPaid + grandTotal;
    const balanceAfter = expected - totalAfterPayment;
    
    if (outstandingSpan) {
        if (balanceAfter > 0) {
            outstandingSpan.innerHTML = `UGX ${balanceAfter.toLocaleString()}`;
            outstandingSpan.className = 'font-bold text-xl text-red-600';
        } else if (balanceAfter < 0) {
            outstandingSpan.innerHTML = `Credit: UGX ${Math.abs(balanceAfter).toLocaleString()}`;
            outstandingSpan.className = 'font-bold text-xl text-blue-600';
        } else {
            outstandingSpan.innerHTML = 'Fully Paid';
            outstandingSpan.className = 'font-bold text-xl text-green-600';
        }
    }
}

// ==================== FIX 2: SET FULL TUITION - RESPECTS MAX LIMIT ====================
function setFullTuitionAmountFixed() {
    const checkbox = document.getElementById('fullTuitionCheck');
    const tuitionInput = document.getElementById('tuitionAmount');
    if (checkbox?.checked && tuitionInput && !tuitionInput.disabled) {
        const maxAmount = parseFloat(tuitionInput.max) || 0;
        tuitionInput.value = maxAmount;
        if (typeof calculateCollectionTotalsFixed === 'function') {
            calculateCollectionTotalsFixed();
        }
    } else if (tuitionInput && !checkbox?.checked) {
        tuitionInput.value = 0;
        if (typeof calculateCollectionTotalsFixed === 'function') {
            calculateCollectionTotalsFixed();
        }
    }
}

// ========== MAKE GLOBAL ==========
window.setFullTuitionAmountFixed = setFullTuitionAmountFixed;
// ==================== SET FULL TUITION FINAL ====================

function setFullTuitionAmountFinal() {
    const checkbox = document.getElementById('fullTuitionCheck');
    const tuitionInput = document.getElementById('tuitionAmount');
    if (checkbox?.checked && tuitionInput) {
        tuitionInput.value = tuitionInput.max;
        calculateAllTotalsFinal();
    } else if (tuitionInput) {
        tuitionInput.value = 0;
        calculateAllTotalsFinal();
    }
}

// ==================== RESET ALL PAYMENTS FINAL ====================

function resetAllPaymentsFinal() {
    const tuitionInput = document.getElementById('tuitionAmount');
    if (tuitionInput) tuitionInput.value = '0';
    
    const fullTuitionCheck = document.getElementById('fullTuitionCheck');
    if (fullTuitionCheck) fullTuitionCheck.checked = false;
    
    document.querySelectorAll('.cashAmountInputFinal, .itemsBroughtInputFinal').forEach(input => {
        input.value = '';
    });
    
    document.querySelectorAll('.paymentTypeRadioFinal[value="cash"]').forEach(radio => {
        radio.checked = true;
    });
    
    document.querySelectorAll('.payment-input-group').forEach(group => {
        if (group.id.startsWith('cashInput')) {
            group.classList.remove('hidden');
        } else if (group.id.startsWith('itemInput')) {
            group.classList.add('hidden');
        }
    });
    
    document.querySelectorAll('[id^="itemTotal_"]').forEach(span => {
        span.innerHTML = 'UGX 0';
    });
    
    document.querySelectorAll('[id^="itemStatus_"]').forEach(span => {
        span.innerHTML = 'Not Paid';
        span.className = 'font-medium px-2 py-0.5 rounded-full bg-red-100 text-red-600';
    });
    
    document.querySelectorAll('[id^="thatToSay_"]').forEach(span => {
        span.innerHTML = '';
    });
    
    ['one_time', 'termly', 'yearly'].forEach(period => {
        const totalSpan = document.getElementById(`${period}TotalAmountFinal`);
        if (totalSpan) totalSpan.innerHTML = 'UGX 0';
    });
    
    const paymentReference = document.getElementById('paymentReference');
    const paymentNotes = document.getElementById('paymentNotes');
    if (paymentReference) paymentReference.value = '';
    if (paymentNotes) paymentNotes.value = '';
    
    calculateAllTotalsFinal();
}

// ==================== SUBMIT FULL PAYMENT ====================

async function submitFullPayment(student, feeStructure, currentYear, currentTerm) {
    const tuitionPaid = parseInt(document.getElementById('tuitionAmount')?.value) || 0;
    const method = document.getElementById('paymentMethodSelect')?.value || 'cash';
    const reference = document.getElementById('paymentReference')?.value || '';
    const notes = document.getElementById('paymentNotes')?.value || '';
    
    const activityItemPayments = [];
    const periodTypes = ['one_time', 'termly', 'yearly'];
    
    for (const periodType of periodTypes) {
        const container = document.getElementById(`${periodType}ItemsContainer`);
        if (!container) continue;
        
        const itemRows = container.querySelectorAll('.bg-white.rounded-lg');
        for (const row of itemRows) {
            const cashInput = row.querySelector('.cashAmountInputFinal');
            const itemsInput = row.querySelector('.itemsBroughtInputFinal');
            if (!cashInput && !itemsInput) continue;
            
            const itemUniqueId = cashInput?.dataset.itemId || itemsInput?.dataset.itemId;
            if (!itemUniqueId) continue;
            
            const cashRadio = row.querySelector('input[value="cash"]');
            const isCash = cashRadio && cashRadio.checked;
            
            let amountPaid = 0, itemsBrought = 0, unitPrice = 0, quantity = 0;
            let itemName = '', componentName = '';
            
            if (isCash) {
                const cashAmountInput = row.querySelector('.cashAmountInputFinal');
                amountPaid = parseFloat(cashAmountInput?.value) || 0;
                if (amountPaid <= 0) continue;
                unitPrice = parseFloat(cashAmountInput?.dataset.unitPrice) || 0;
                quantity = parseInt(cashAmountInput?.dataset.quantity) || 0;
                itemName = row.querySelector('h4')?.innerText?.replace('📦 ', '') || '';
                componentName = row.querySelector('.text-xs.text-gray-500')?.innerText || '';
            } else {
                const itemsBroughtInput = row.querySelector('.itemsBroughtInputFinal');
                itemsBrought = parseInt(itemsBroughtInput?.value) || 0;
                if (itemsBrought <= 0) continue;
                unitPrice = parseFloat(itemsBroughtInput?.dataset.unitPrice) || 0;
                quantity = parseInt(itemsBroughtInput?.dataset.quantity) || 0;
                itemName = row.querySelector('h4')?.innerText?.replace('📦 ', '') || '';
                componentName = row.querySelector('.text-xs.text-gray-500')?.innerText || '';
            }
            
            activityItemPayments.push({
                periodType: periodType,
                itemName: itemName,
                componentName: componentName,
                unitPrice: unitPrice,
                quantity: quantity,
                paymentType: isCash ? 'paid_cash' : 'brought_item',
                amountPaid: isCash ? amountPaid : null,
                itemsBrought: !isCash ? itemsBrought : null,
                cashEquivalent: !isCash ? (itemsBrought * unitPrice) : null
            });
        }
    }
    
    const activityTotal = activityItemPayments.reduce((sum, p) => 
        sum + (p.paymentType === 'paid_cash' ? (p.amountPaid || 0) : (p.cashEquivalent || 0)), 0);
    const totalAmount = tuitionPaid + activityTotal;
    
    if (totalAmount <= 0) {
        alert('Please enter an amount to pay or select items to pay');
        return;
    }
    
    const submitBtn = document.querySelector('#collectionForm button[type="submit"]');
    const originalText = submitBtn.innerText;
    submitBtn.innerText = 'Processing...';
    submitBtn.disabled = true;
    
    try {
        const response = await fetch('/api/fee/payments/enhanced', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                studentId: student.id,
                studentName: `${student.firstName} ${student.lastName}`,
                admissionNumber: student.admissionNumber,
                term: currentTerm,
                academicYear: currentYear.toString(),
                feeStructureId: feeStructure?.id || null,
                feeStructureName: feeStructure?.name || 'General Fee',
                bursaryId: student.appliedBursary?.id || null,
                bursaryName: student.appliedBursary?.name || null,
                tuitionPaid: tuitionPaid,
                activityItemPayments: activityItemPayments,
                totalAmount: totalAmount,
                method: method,
                reference: reference,
                notes: notes,
                isFirstPaymentOfTerm: student.totalPaid === 0
            })
        });
        
        if (response.ok) {
            const result = await response.json();
            alert(`✅ Payment recorded successfully!\nReceipt: ${result.receiptNumber}\nAmount: UGX ${totalAmount.toLocaleString()}`);
            showFeeManagement();
        } else {
            const error = await response.json();
            alert('❌ Error: ' + (error.error || 'Unknown error'));
        }
    } catch (error) {
        console.error('Payment error:', error);
        alert('Network error: ' + error.message);
    } finally {
        submitBtn.innerText = originalText;
        submitBtn.disabled = false;
    }
}

